  "You are viewing this workspace read-only. Nothing you do here is saved.": "ਤੁਸੀਂ ਇਹ ਵਰਕਸਪੇਸ ਸਿਰਫ਼ ਵੇਖਣ ਲਈ ਖੋਲ੍ਹਿਆ ਹੈ। ਇੱਥੇ ਤੁਸੀਂ ਜੋ ਵੀ ਕਰੋਗੇ ਉਹ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹੋਵੇਗਾ।",
  "Requests are recorded against your employee record and routed to the approver shown on each one.": "ਬੇਨਤੀਆਂ ਤੁਹਾਡੇ ਕਰਮਚਾਰੀ ਰਿਕਾਰਡ ਵਿੱਚ ਦਰਜ ਹੁੰਦੀਆਂ ਹਨ ਅਤੇ ਹਰ ਬੇਨਤੀ ਉੱਤੇ ਦਿਖਾਏ ਮਨਜ਼ੂਰੀ ਦੇਣ ਵਾਲੇ ਕੋਲ ਭੇਜੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।",
