  "Changes employees ask HR to make to their profile. Everyone who answers HR Help tickets, and any full-access user, sees all of them.": "ਕਰਮਚਾਰੀ HR ਨੂੰ ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ ਵਿੱਚ ਜੋ ਤਬਦੀਲੀਆਂ ਕਰਨ ਲਈ ਕਹਿੰਦੇ ਹਨ। HR ਮਦਦ ਟਿਕਟਾਂ ਦਾ ਜਵਾਬ ਦੇਣ ਵਾਲਾ ਹਰ ਕੋਈ, ਅਤੇ ਪੂਰੀ ਪਹੁੰਚ ਵਾਲਾ ਕੋਈ ਵੀ ਵਰਤੋਂਕਾਰ, ਇਹ ਸਾਰੀਆਂ ਵੇਖਦਾ ਹੈ।",
  "Counts show only what the server lets you see. Onboarding approvals are in Review & Onboarding, and bank-change requests are in the employee record; they are not part of this list.": "ਗਿਣਤੀ ਸਿਰਫ਼ ਉਹੀ ਦਿਖਾਉਂਦੀ ਹੈ ਜੋ ਸਰਵਰ ਤੁਹਾਨੂੰ ਵੇਖਣ ਦਿੰਦਾ ਹੈ। ਆਨਬੋਰਡਿੰਗ ਮਨਜ਼ੂਰੀਆਂ \"ਸਮੀਖਿਆ ਅਤੇ ਆਨਬੋਰਡਿੰਗ\" ਵਿੱਚ ਹਨ, ਅਤੇ ਬੈਂਕ ਬਦਲਾਅ ਦੀਆਂ ਬੇਨਤੀਆਂ ਕਰਮਚਾਰੀ ਰਿਕਾਰਡ ਵਿੱਚ ਹਨ; ਉਹ ਇਸ ਸੂਚੀ ਦਾ ਹਿੱਸਾ ਨਹੀਂ ਹਨ।",
  "Cycle sign-off for your team or payroll scope. Open the tab to see what is due.": "ਤੁਹਾਡੀ ਟੀਮ ਜਾਂ ਪੇਰੋਲ ਦਾਇਰੇ ਲਈ ਚੱਕਰ ਦੇ ਦਸਤਖਤ। ਕੀ ਬਾਕੀ ਹੈ ਇਹ ਵੇਖਣ ਲਈ ਟੈਬ ਖੋਲ੍ਹੋ।",
