  "WFH, field work, biometric failure…": "WFH, ਫੀਲਡ ਕੰਮ, ਬਾਇਓਮੈਟ੍ਰਿਕ ਖਰਾਬੀ…",
  ". Employees cannot register a face ID or be asked to verify — their Profile page shows “Contact admin to use this feature”, and no punch requires a face match.": "। ਕਰਮਚਾਰੀ Face ID ਰਜਿਸਟਰ ਨਹੀਂ ਕਰ ਸਕਦੇ ਅਤੇ ਨਾ ਹੀ ਉਨ੍ਹਾਂ ਤੋਂ ਪੁਸ਼ਟੀ ਮੰਗੀ ਜਾਂਦੀ ਹੈ — ਉਨ੍ਹਾਂ ਦੇ ਪ੍ਰੋਫਾਈਲ ਪੰਨੇ ਤੇ “ਇਹ ਸਹੂਲਤ ਵਰਤਣ ਲਈ ਐਡਮਿਨ ਨਾਲ ਸੰਪਰਕ ਕਰੋ” ਦਿਖਾਈ ਦਿੰਦਾ ਹੈ, ਅਤੇ ਕਿਸੇ ਵੀ ਪੰਚ ਲਈ ਚਿਹਰੇ ਦਾ ਮੇਲ ਲੋੜੀਂਦਾ ਨਹੀਂ।",
