  "9 hours": "9 ਘੰਟੇ",
  "A fallback punch must still be from inside the office geofence. It is flagged on the punch and recorded in the Audit Log.": "ਬਦਲਵਾਂ ਪੰਚ ਵੀ ਦਫ਼ਤਰ ਦੀ ਜੀਓਫੈਂਸ ਦੇ ਅੰਦਰੋਂ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ। ਇਹ ਪੰਚ ਉੱਤੇ ਚਿੰਨ੍ਹਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ ਅਤੇ ਆਡਿਟ ਲੌਗ ਵਿੱਚ ਦਰਜ ਹੁੰਦਾ ਹੈ।",
