  "Early Exit Grace": "ਜਲਦੀ ਨਿਕਲਣ ਦੀ ਛੋਟ",
  "Every message (the clock-in error, the Profile page, the Face ID Registrations screen, the hire screen and the welcome email) follows this choice.": "ਹਰ ਸੁਨੇਹਾ (ਕਲੌਕ-ਇਨ ਗਲਤੀ, ਪ੍ਰੋਫਾਈਲ ਪੰਨਾ, Face ID ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਸਕ੍ਰੀਨ, ਭਰਤੀ ਸਕ੍ਰੀਨ ਅਤੇ ਸਵਾਗਤ ਈਮੇਲ) ਇਸ ਚੋਣ ਦੀ ਪਾਲਣਾ ਕਰਦਾ ਹੈ।",
  "Face ID registration is": "Face ID ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਹੈ",
  "Face ID Verification": "Face ID ਪੁਸ਼ਟੀ",
  "Face ID verification is": "Face ID ਪੁਸ਼ਟੀ ਹੈ",
  "for every employee. Every web punch needs a live face match against an approved Face ID; until one exists, web clock-in/out is blocked unless you allow the fallback below.": "ਹਰ ਕਰਮਚਾਰੀ ਲਈ। ਹਰ ਵੈੱਬ ਪੰਚ ਲਈ ਮਨਜ਼ੂਰ ਕੀਤੇ Face ID ਨਾਲ ਲਾਈਵ ਚਿਹਰੇ ਦਾ ਮੇਲ ਲੋੜੀਂਦਾ ਹੈ; ਜਦੋਂ ਤੱਕ ਕੋਈ ਨਹੀਂ ਬਣਦਾ, ਵੈੱਬ ਕਲੌਕ-ਇਨ/ਆਊਟ ਬੰਦ ਰਹਿੰਦਾ ਹੈ ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਹੇਠਾਂ ਦਿੱਤੇ ਬਦਲ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਦਿੰਦੇ।",
  "Forgive late arrival when full hours are completed": "ਪੂਰੇ ਘੰਟੇ ਪੂਰੇ ਕਰਨ ਤੇ ਦੇਰ ਨਾਲ ਆਉਣਾ ਮਾਫ਼ ਕਰੋ",
  "Grace Period (min)": "ਛੋਟ ਦੀ ਮਿਆਦ (ਮਿੰਟ)",
  "Half-Day Limit (hours or fewer)": "ਅੱਧੇ ਦਿਨ ਦੀ ਸੀਮਾ (ਇੰਨੇ ਘੰਟੇ ਜਾਂ ਘੱਟ)",
  "How many days back an employee can request work from home. Not allowed (recommended): today or a later date only, because an approved request for a past day relabels that day after the fact and the home-location check cannot be met.": "ਕਰਮਚਾਰੀ ਕਿੰਨੇ ਦਿਨ ਪਿੱਛੇ ਤੱਕ ਘਰ ਤੋਂ ਕੰਮ ਦੀ ਬੇਨਤੀ ਕਰ ਸਕਦਾ ਹੈ। ਇਜਾਜ਼ਤ ਨਹੀਂ (ਸਿਫ਼ਾਰਸ਼ੀ): ਸਿਰਫ਼ ਅੱਜ ਜਾਂ ਬਾਅਦ ਦੀ ਤਾਰੀਖ, ਕਿਉਂਕਿ ਬੀਤੇ ਦਿਨ ਲਈ ਮਨਜ਼ੂਰ ਹੋਈ ਬੇਨਤੀ ਉਸ ਦਿਨ ਨੂੰ ਬਾਅਦ ਵਿੱਚ ਬਦਲ ਦਿੰਦੀ ਹੈ ਅਤੇ ਘਰ ਦੇ ਸਥਾਨ ਦੀ ਜਾਂਚ ਪੂਰੀ ਨਹੀਂ ਹੋ ਸਕਦੀ।",
  "HR only": "ਸਿਰਫ਼ HR",
  "Late Mark & LOP Rule": "ਦੇਰ ਦਾ ਨਿਸ਼ਾਨ ਅਤੇ LOP ਨਿਯਮ",
  "Late Marks per LOP": "ਪ੍ਰਤੀ LOP ਦੇਰ ਦੇ ਨਿਸ਼ਾਨ",
  "Loading settings…": "ਸੈਟਿੰਗਾਂ ਲੋਡ ਹੋ ਰਹੀਆਂ ਹਨ…",
  "LOP Deduction Unit": "LOP ਕਟੌਤੀ ਇਕਾਈ",
  "Manager + HR": "ਮੈਨੇਜਰ + HR",
  "Manager only": "ਸਿਰਫ਼ ਮੈਨੇਜਰ",
  "mandatory": "ਲਾਜ਼ਮੀ",
  "Min Hours — Full Day": "ਘੱਟੋ-ਘੱਟ ਘੰਟੇ — ਪੂਰਾ ਦਿਨ",
  "No LOP (tracking only)": "ਕੋਈ LOP ਨਹੀਂ (ਸਿਰਫ਼ ਟ੍ਰੈਕਿੰਗ)",
  "Not allowed (today or later)": "ਇਜਾਜ਼ਤ ਨਹੀਂ (ਅੱਜ ਜਾਂ ਬਾਅਦ ਵਿੱਚ)",
  "Notify": "ਸੂਚਿਤ ਕਰੋ",
  "Notify HR and the manager when an employee is absent for N+ consecutive working days without approved leave.": "ਜਦੋਂ ਕੋਈ ਕਰਮਚਾਰੀ ਮਨਜ਼ੂਰ ਛੁੱਟੀ ਤੋਂ ਬਿਨਾਂ ਲਗਾਤਾਰ N+ ਕੰਮ ਦੇ ਦਿਨ ਗੈਰਹਾਜ਼ਰ ਰਹੇ ਤਾਂ HR ਅਤੇ ਮੈਨੇਜਰ ਨੂੰ ਸੂਚਿਤ ਕਰੋ।",
  "off": "ਬੰਦ",
  "Off (recommended): a finished day of the half-day limit or fewer is a Half Day; a day above it but short of the full-day minimum stays Present and is shown as “hours not completed” with the minutes short. On: every day below the full-day minimum is a Half Day.": "ਬੰਦ (ਸਿਫ਼ਾਰਸ਼ੀ): ਅੱਧੇ ਦਿਨ ਦੀ ਸੀਮਾ ਜਾਂ ਉਸ ਤੋਂ ਘੱਟ ਵਾਲਾ ਪੂਰਾ ਹੋਇਆ ਦਿਨ ਅੱਧਾ ਦਿਨ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ; ਉਸ ਤੋਂ ਵੱਧ ਪਰ ਪੂਰੇ ਦਿਨ ਦੇ ਘੱਟੋ-ਘੱਟ ਤੋਂ ਘੱਟ ਵਾਲਾ ਦਿਨ ਹਾਜ਼ਰ ਹੀ ਰਹਿੰਦਾ ਹੈ ਅਤੇ ਘੱਟ ਮਿੰਟਾਂ ਸਮੇਤ “ਘੰਟੇ ਪੂਰੇ ਨਹੀਂ ਹੋਏ” ਵਜੋਂ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ। ਚਾਲੂ: ਪੂਰੇ ਦਿਨ ਦੇ ਘੱਟੋ-ਘੱਟ ਤੋਂ ਘੱਟ ਹਰ ਦਿਨ ਅੱਧਾ ਦਿਨ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ।",
  "OT Multiplier — Holiday": "ਓਵਰਟਾਈਮ ਗੁਣਕ — ਛੁੱਟੀ",
  "OT Multiplier — Regular": "ਓਵਰਟਾਈਮ ਗੁਣਕ — ਆਮ",
  "OT Threshold": "ਓਵਰਟਾਈਮ ਸੀਮਾ",
  "Overtime Rules": "ਓਵਰਟਾਈਮ ਨਿਯਮ",
  "Punch Rules": "ਪੰਚ ਨਿਯਮ",
  "Resets each calendar month": "ਹਰ ਕੈਲੰਡਰ ਮਹੀਨੇ ਰੀਸੈੱਟ ਹੁੰਦਾ ਹੈ",
  "Save All": "ਸਭ ਸੁਰੱਖਿਅਤ ਕਰੋ",
  "Shift End": "ਸ਼ਿਫਟ ਦਾ ਅੰਤ",
  "Shift Start": "ਸ਼ਿਫਟ ਦੀ ਸ਼ੁਰੂਆਤ",
  "Someone who arrives after the grace period but works the full-day hours is marked Present and gets no late mark. The late arrival stays as a note.": "ਜੋ ਵਿਅਕਤੀ ਛੋਟ ਦੀ ਮਿਆਦ ਤੋਂ ਬਾਅਦ ਆਉਂਦਾ ਹੈ ਪਰ ਪੂਰੇ ਦਿਨ ਦੇ ਘੰਟੇ ਕੰਮ ਕਰਦਾ ਹੈ, ਉਸਨੂੰ ਹਾਜ਼ਰ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਦੇਰ ਦਾ ਨਿਸ਼ਾਨ ਨਹੀਂ ਲੱਗਦਾ। ਦੇਰ ਨਾਲ ਆਉਣਾ ਇੱਕ ਨੋਟ ਵਜੋਂ ਰਹਿੰਦਾ ਹੈ।",
  "Treat every day below the full day as a Half Day": "ਪੂਰੇ ਦਿਨ ਤੋਂ ਘੱਟ ਹਰ ਦਿਨ ਨੂੰ ਅੱਧਾ ਦਿਨ ਗਿਣੋ",
  "Up to 1 day back": "1 ਦਿਨ ਪਿੱਛੇ ਤੱਕ",
  "Up to 2 days back": "2 ਦਿਨ ਪਿੱਛੇ ਤੱਕ",
  "Up to 3 days back": "3 ਦਿਨ ਪਿੱਛੇ ਤੱਕ",
  "Up to 7 days back": "7 ਦਿਨ ਪਿੱਛੇ ਤੱਕ",
