  "This assigns \"{pattern}\" effective {date} to every active employee matching: {scope}. The exact number of employees affected is resolved on the server and isn't known until this runs.": "ਇਹ \"{pattern}\" ਨੂੰ {date} ਤੋਂ ਲਾਗੂ ਕਰਕੇ ਮੇਲ ਖਾਂਦੇ ਹਰ ਸਰਗਰਮ ਕਰਮਚਾਰੀ ਨੂੰ ਸੌਂਪਦਾ ਹੈ: {scope}। ਪ੍ਰਭਾਵਿਤ ਕਰਮਚਾਰੀਆਂ ਦੀ ਸਹੀ ਗਿਣਤੀ ਸਰਵਰ ਤੇ ਤੈਅ ਹੁੰਦੀ ਹੈ ਅਤੇ ਇਹ ਚੱਲਣ ਤੋਂ ਪਹਿਲਾਂ ਪਤਾ ਨਹੀਂ ਹੁੰਦੀ।",
