  "Weekly off pattern assigned to {count} employee(s).": "ਹਫ਼ਤਾਵਾਰੀ ਛੁੱਟੀ ਪੈਟਰਨ {count} ਕਰਮਚਾਰੀ(ਆਂ) ਨੂੰ ਸੌਂਪਿਆ ਗਿਆ।",
  "Weekly off pattern assigned to {name}.": "ਹਫ਼ਤਾਵਾਰੀ ਛੁੱਟੀ ਪੈਟਰਨ {name} ਨੂੰ ਸੌਂਪਿਆ ਗਿਆ।",
  "Which weekly off pattern each employee follows. A new pattern applies from its effective date forward.": "ਹਰ ਕਰਮਚਾਰੀ ਕਿਹੜੇ ਹਫ਼ਤਾਵਾਰੀ ਛੁੱਟੀ ਪੈਟਰਨ ਦੀ ਪਾਲਣਾ ਕਰਦਾ ਹੈ। ਨਵਾਂ ਪੈਟਰਨ ਆਪਣੀ ਲਾਗੂ ਹੋਣ ਦੀ ਤਾਰੀਖ ਤੋਂ ਅੱਗੇ ਲਈ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।",
  "\"{name}\" will be deactivated. Employees currently assigned this pattern keep it until reassigned — history is preserved.": "\"{name}\" ਨੂੰ ਬੰਦ ਕਰ ਦਿੱਤਾ ਜਾਵੇਗਾ। ਜਿਨ੍ਹਾਂ ਕਰਮਚਾਰੀਆਂ ਨੂੰ ਇਹ ਪੈਟਰਨ ਇਸ ਵੇਲੇ ਸੌਂਪਿਆ ਹੈ ਉਹ ਦੁਬਾਰਾ ਸੌਂਪੇ ਜਾਣ ਤੱਕ ਇਸਨੂੰ ਰੱਖਦੇ ਹਨ — ਇਤਿਹਾਸ ਸੁਰੱਖਿਅਤ ਰਹਿੰਦਾ ਹੈ।",
