  "Configure reusable weekly-off schedules and assign them to employees from Attendance & Time → Weekly Off Assignment.": "ਮੁੜ ਵਰਤੋਂ ਯੋਗ ਹਫ਼ਤਾਵਾਰੀ ਛੁੱਟੀ ਦੇ ਸ਼ਡਿਊਲ ਸੈੱਟ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਹਾਜ਼ਰੀ ਅਤੇ ਸਮਾਂ → ਹਫ਼ਤਾਵਾਰੀ ਛੁੱਟੀ ਦੀ ਨਿਯੁਕਤੀ ਤੋਂ ਕਰਮਚਾਰੀਆਂ ਨੂੰ ਸੌਂਪੋ।",
