  "Nominees are chosen from this list, and the parents' names on step 1 are filled from it. Add family before setting nominations.": "ਨਾਮਜ਼ਦ ਇਸ ਸੂਚੀ ਵਿੱਚੋਂ ਚੁਣੇ ਜਾਂਦੇ ਹਨ, ਅਤੇ ਪਹਿਲੇ ਪੜਾਅ ਵਿੱਚ ਮਾਪਿਆਂ ਦੇ ਨਾਮ ਇਸ ਵਿੱਚੋਂ ਭਰੇ ਜਾਂਦੇ ਹਨ। ਨਾਮਜ਼ਦਗੀ ਤੈਅ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਪਰਿਵਾਰ ਜੋੜੋ।",
  "Not required of a private employer. Collect only where a government, PSU or aided establishment must report it, or a state incentive scheme requires it. Self-declared, and hidden from reporting managers.": "ਨਿੱਜੀ ਮਾਲਕ ਲਈ ਲਾਜ਼ਮੀ ਨਹੀਂ। ਸਿਰਫ਼ ਉੱਥੇ ਲਓ ਜਿੱਥੇ ਸਰਕਾਰੀ, PSU ਜਾਂ ਸਹਾਇਤਾ-ਪ੍ਰਾਪਤ ਅਦਾਰੇ ਨੂੰ ਇਹ ਰਿਪੋਰਟ ਕਰਨਾ ਪੈਂਦਾ ਹੈ, ਜਾਂ ਰਾਜ ਦੀ ਪ੍ਰੋਤਸਾਹਨ ਯੋਜਨਾ ਇਸਦੀ ਮੰਗ ਕਰਦੀ ਹੈ। ਇਹ ਸਵੈ-ਘੋਸ਼ਿਤ ਹੈ ਅਤੇ ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰਾਂ ਤੋਂ ਲੁਕਾਈ ਜਾਂਦੀ ਹੈ।",
  "Nothing outstanding": "ਕੁਝ ਵੀ ਬਾਕੀ ਨਹੀਂ",
  "Only required if a nominee above is under 18.": "ਸਿਰਫ਼ ਤਾਂ ਹੀ ਲਾਜ਼ਮੀ ਜੇ ਉੱਪਰ ਦਾ ਕੋਈ ਨਾਮਜ਼ਦ 18 ਸਾਲ ਤੋਂ ਘੱਟ ਹੈ।",
  "OPTIONAL, not yet stored post-hire": "ਵਿਕਲਪਿਕ, ਭਰਤੀ ਤੋਂ ਬਾਅਦ ਹਾਲੇ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾਂਦਾ",
  "Place of birth": "ਜਨਮ ਸਥਾਨ",
  "Position, reporting line, work setup and pay.": "ਅਹੁਦਾ, ਰਿਪੋਰਟਿੰਗ ਲਾਈਨ, ਕੰਮ ਦੀ ਸੈਟਿੰਗ ਅਤੇ ਤਨਖਾਹ।",
