  "record": "ਰਿਕਾਰਡ",
  "Record-keeping obligation under the RPwD Act 2016.": "RPwD ਐਕਟ 2016 ਅਧੀਨ ਰਿਕਾਰਡ ਰੱਖਣ ਦੀ ਜ਼ਿੰਮੇਵਾਰੀ।",
  "Required for EPF Form 2. Nominees are picked from the family list, so a name is only typed once. Each scheme should total 100%.": "EPF ਫਾਰਮ 2 ਲਈ ਲਾਜ਼ਮੀ। ਨਾਮਜ਼ਦ ਪਰਿਵਾਰ ਦੀ ਸੂਚੀ ਵਿੱਚੋਂ ਚੁਣੇ ਜਾਂਦੇ ਹਨ, ਇਸ ਲਈ ਨਾਮ ਸਿਰਫ਼ ਇੱਕ ਵਾਰ ਲਿਖਣਾ ਪੈਂਦਾ ਹੈ। ਹਰ ਯੋਜਨਾ ਦਾ ਕੁੱਲ 100% ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
