  "Leave empty for a fresher — total experience reads zero. Experience is counted up to the joining date.": "ਨਵੇਂ ਉਮੀਦਵਾਰ ਲਈ ਖਾਲੀ ਛੱਡੋ — ਕੁੱਲ ਤਜਰਬਾ ਜ਼ੀਰੋ ਦਿਖਾਇਆ ਜਾਵੇਗਾ। ਤਜਰਬਾ ਸ਼ਾਮਲ ਹੋਣ ਦੀ ਤਾਰੀਖ ਤੱਕ ਗਿਣਿਆ ਜਾਂਦਾ ਹੈ।",
