  "Monthly amounts derived from the annual CTC in Employment. Any earning can be overridden; Special Allowance balances back to CTC and the statutory rows recalculate.": "ਮਾਸਿਕ ਰਕਮਾਂ ਨੌਕਰੀ ਵਿੱਚ ਦਿੱਤੇ ਸਾਲਾਨਾ CTC ਤੋਂ ਕੱਢੀਆਂ ਗਈਆਂ ਹਨ। ਕੋਈ ਵੀ ਕਮਾਈ ਬਦਲੀ ਜਾ ਸਕਦੀ ਹੈ; ਵਿਸ਼ੇਸ਼ ਭੱਤਾ CTC ਨਾਲ ਸੰਤੁਲਿਤ ਹੋ ਜਾਂਦਾ ਹੈ ਅਤੇ ਕਾਨੂੰਨੀ ਕਤਾਰਾਂ ਦੁਬਾਰਾ ਗਿਣੀਆਂ ਜਾਂਦੀਆਂ ਹਨ।",
