  "Monthly amounts use the selected salary structure and effective date. Enabled structure components appear here; statutory contributions and deductions remain governed by payroll eligibility and statutory rules.": "ਮਾਸਿਕ ਰਕਮਾਂ ਚੁਣੇ ਤਨਖਾਹ ਢਾਂਚੇ ਅਤੇ ਲਾਗੂ ਹੋਣ ਦੀ ਤਾਰੀਖ ਅਨੁਸਾਰ ਹਨ। ਚਾਲੂ ਕੀਤੇ ਢਾਂਚੇ ਦੇ ਭਾਗ ਇੱਥੇ ਦਿਖਾਈ ਦਿੰਦੇ ਹਨ; ਕਾਨੂੰਨੀ ਯੋਗਦਾਨ ਅਤੇ ਕਟੌਤੀਆਂ ਪੇਰੋਲ ਯੋਗਤਾ ਅਤੇ ਕਾਨੂੰਨੀ ਨਿਯਮਾਂ ਅਨੁਸਾਰ ਹੀ ਰਹਿੰਦੀਆਂ ਹਨ।",
