  "No salary structure applies to this employee. Add or activate one in Settings → Payroll Configuration → Salary Structures; pay components come from it.": "ਇਸ ਕਰਮਚਾਰੀ ਤੇ ਕੋਈ ਤਨਖਾਹ ਢਾਂਚਾ ਲਾਗੂ ਨਹੀਂ ਹੁੰਦਾ। ਸੈਟਿੰਗਾਂ → ਪੇਰੋਲ ਸੰਰਚਨਾ → ਤਨਖਾਹ ਢਾਂਚੇ ਵਿੱਚ ਇੱਕ ਜੋੜੋ ਜਾਂ ਚਾਲੂ ਕਰੋ; ਤਨਖਾਹ ਦੇ ਭਾਗ ਉਸ ਤੋਂ ਆਉਂਦੇ ਹਨ।",
