  "Non-statutory fields erasable on request; statutory records cannot be deleted early": "ਗੈਰ-ਕਾਨੂੰਨੀ ਖੇਤਰ ਬੇਨਤੀ ਤੇ ਮਿਟਾਏ ਜਾ ਸਕਦੇ ਹਨ; ਕਾਨੂੰਨੀ ਰਿਕਾਰਡ ਸਮੇਂ ਤੋਂ ਪਹਿਲਾਂ ਨਹੀਂ ਮਿਟਾਏ ਜਾ ਸਕਦੇ",
