  "This account has no employee record on file (no employee number assigned), so employment, pay, statutory, and history details below are unavailable. This is expected for an admin/system login that was never onboarded as an employee — sign in as an onboarded employee to see a full record.": "ਇਸ ਖਾਤੇ ਦਾ ਕੋਈ ਕਰਮਚਾਰੀ ਰਿਕਾਰਡ ਨਹੀਂ ਹੈ (ਕੋਈ ਕਰਮਚਾਰੀ ਨੰਬਰ ਨਹੀਂ ਦਿੱਤਾ ਗਿਆ), ਇਸ ਲਈ ਹੇਠਾਂ ਨੌਕਰੀ, ਤਨਖਾਹ, ਕਾਨੂੰਨੀ ਅਤੇ ਇਤਿਹਾਸ ਦਾ ਵੇਰਵਾ ਉਪਲਬਧ ਨਹੀਂ ਹੈ। ਜਿਸ ਐਡਮਿਨ/ਸਿਸਟਮ ਲੌਗਇਨ ਨੂੰ ਕਦੇ ਕਰਮਚਾਰੀ ਵਜੋਂ ਆਨਬੋਰਡ ਨਹੀਂ ਕੀਤਾ ਗਿਆ, ਉਸ ਲਈ ਇਹ ਆਮ ਗੱਲ ਹੈ — ਪੂਰਾ ਰਿਕਾਰਡ ਵੇਖਣ ਲਈ ਆਨਬੋਰਡ ਹੋਏ ਕਰਮਚਾਰੀ ਵਜੋਂ ਸਾਈਨ ਇਨ ਕਰੋ।",
  "This employee submitted a bank detail change awaiting your review — their previous details remain active for payroll until you decide.": "ਇਸ ਕਰਮਚਾਰੀ ਨੇ ਬੈਂਕ ਵੇਰਵੇ ਵਿੱਚ ਤਬਦੀਲੀ ਜਮ੍ਹਾਂ ਕੀਤੀ ਹੈ ਜੋ ਤੁਹਾਡੀ ਸਮੀਖਿਆ ਦੀ ਉਡੀਕ ਵਿੱਚ ਹੈ — ਤੁਹਾਡੇ ਫੈਸਲੇ ਤੱਕ ਪੇਰੋਲ ਲਈ ਉਨ੍ਹਾਂ ਦਾ ਪਿਛਲਾ ਵੇਰਵਾ ਹੀ ਚਾਲੂ ਰਹੇਗਾ।",
