  "Each new employee then gets an activation email.": "ਫਿਰ ਹਰ ਨਵੇਂ ਕਰਮਚਾਰੀ ਨੂੰ ਇੱਕ ਐਕਟੀਵੇਸ਼ਨ ਈਮੇਲ ਮਿਲਦੀ ਹੈ।",
