  "This cannot be undone": "ਇਹ ਵਾਪਸ ਨਹੀਂ ਹੋ ਸਕਦਾ",
  "unchanged": "ਬਦਲਿਆ ਨਹੀਂ",
  "HR Business Partner → Payroll Admin.": "HR ਬਿਜ਼ਨਸ ਪਾਰਟਨਰ → ਪੇਰੋਲ ਐਡਮਿਨ।",
  "HR, then Branch Admin (this employee is a manager, per the real separation approval chain).": "HR, ਫਿਰ ਸ਼ਾਖਾ ਐਡਮਿਨ (ਇਹ ਕਰਮਚਾਰੀ ਮੈਨੇਜਰ ਹੈ, ਅਸਲੀ ਸੇਵਾ-ਸਮਾਪਤੀ ਮਨਜ਼ੂਰੀ ਲੜੀ ਅਨੁਸਾਰ)।",
  "Not reversible. Undoing a separation requires a fresh Hire action and a new employee record — the original number is not reissued.": "ਵਾਪਸੀਯੋਗ ਨਹੀਂ। ਸੇਵਾ-ਸਮਾਪਤੀ ਨੂੰ ਪਲਟਣ ਲਈ ਨਵੀਂ ਭਰਤੀ ਕਾਰਵਾਈ ਅਤੇ ਨਵੇਂ ਕਰਮਚਾਰੀ ਰਿਕਾਰਡ ਦੀ ਲੋੜ ਹੈ — ਅਸਲ ਨੰਬਰ ਦੁਬਾਰਾ ਜਾਰੀ ਨਹੀਂ ਕੀਤਾ ਜਾਂਦਾ।",
  "Reporting manager (raises) → HR Business Partner, then Payroll Admin if a new CTC is included.": "ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰ (ਬੇਨਤੀ ਕਰਦਾ ਹੈ) → HR ਬਿਜ਼ਨਸ ਪਾਰਟਨਰ, ਫਿਰ ਪੇਰੋਲ ਐਡਮਿਨ ਜੇ ਨਵਾਂ CTC ਸ਼ਾਮਲ ਹੈ।",
  "Reporting manager (raises) → HR Business Partner.": "ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰ (ਬੇਨਤੀ ਕਰਦਾ ਹੈ) → HR ਬਿਜ਼ਨਸ ਪਾਰਟਨਰ।",
  "Reporting manager, then HR (the real separation approval chain for this employee).": "ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰ, ਫਿਰ HR (ਇਸ ਕਰਮਚਾਰੀ ਲਈ ਅਸਲੀ ਸੇਵਾ-ਸਮਾਪਤੀ ਮਨਜ਼ੂਰੀ ਲੜੀ)।",
  "Requires employees.confirm — HR/Admin applies this directly, with the effective date and reason recorded in the audit trail.": "employees.confirm ਦੀ ਲੋੜ ਹੈ — HR/ਐਡਮਿਨ ਇਸਨੂੰ ਸਿੱਧਾ ਲਾਗੂ ਕਰਦਾ ਹੈ, ਲਾਗੂ ਹੋਣ ਦੀ ਤਾਰੀਖ ਅਤੇ ਕਾਰਨ ਆਡਿਟ ਟ੍ਰੇਲ ਵਿੱਚ ਦਰਜ ਹੁੰਦੇ ਹਨ।",
  "Requires employees.edit — applied directly by whoever has that permission (typically the reporting manager or HR); no queued approval step exists for this action yet.": "employees.edit ਦੀ ਲੋੜ ਹੈ — ਜਿਸ ਕੋਲ ਇਹ ਇਜਾਜ਼ਤ ਹੈ (ਆਮ ਤੌਰ ਤੇ ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰ ਜਾਂ HR) ਉਹ ਇਸਨੂੰ ਸਿੱਧਾ ਲਾਗੂ ਕਰਦਾ ਹੈ; ਇਸ ਕਾਰਵਾਈ ਲਈ ਹਾਲੇ ਕੋਈ ਕਤਾਰਬੱਧ ਮਨਜ਼ੂਰੀ ਪੜਾਅ ਨਹੀਂ ਹੈ।",
  "Requires employees.edit — currently held by {name} or HR; no queued approval step exists for this action yet.": "employees.edit ਦੀ ਲੋੜ ਹੈ — ਇਸ ਵੇਲੇ {name} ਜਾਂ HR ਕੋਲ ਹੈ; ਇਸ ਕਾਰਵਾਈ ਲਈ ਹਾਲੇ ਕੋਈ ਕਤਾਰਬੱਧ ਮਨਜ਼ੂਰੀ ਪੜਾਅ ਨਹੀਂ ਹੈ।",
  "Requires employees.edit; no queued approval step exists for this action yet.": "employees.edit ਦੀ ਲੋੜ ਹੈ; ਇਸ ਕਾਰਵਾਈ ਲਈ ਹਾਲੇ ਕੋਈ ਕਤਾਰਬੱਧ ਮਨਜ਼ੂਰੀ ਪੜਾਅ ਨਹੀਂ ਹੈ।",
  "Requires payroll.edit — typically an HR Business Partner or Payroll Admin; no queued approval step exists for this action yet.": "payroll.edit ਦੀ ਲੋੜ ਹੈ — ਆਮ ਤੌਰ ਤੇ HR ਬਿਜ਼ਨਸ ਪਾਰਟਨਰ ਜਾਂ ਪੇਰੋਲ ਐਡਮਿਨ; ਇਸ ਕਾਰਵਾਈ ਲਈ ਹਾਲੇ ਕੋਈ ਕਤਾਰਬੱਧ ਮਨਜ਼ੂਰੀ ਪੜਾਅ ਨਹੀਂ ਹੈ।",
  "Reversible going forward, but any payroll run already processed on this record must be corrected through arrears.": "ਅੱਗੇ ਲਈ ਵਾਪਸੀਯੋਗ ਹੈ, ਪਰ ਇਸ ਰਿਕਾਰਡ ਉੱਤੇ ਪਹਿਲਾਂ ਹੀ ਪ੍ਰੋਸੈਸ ਹੋ ਚੁੱਕੇ ਕਿਸੇ ਵੀ ਪੇਰੋਲ ਨੂੰ ਬਕਾਏ ਰਾਹੀਂ ਠੀਕ ਕਰਨਾ ਪਵੇਗਾ।",
  "Reversible. A correction action delimits this record and restores the previous position; the history keeps both.": "ਵਾਪਸੀਯੋਗ। ਸੁਧਾਈ ਕਾਰਵਾਈ ਇਸ ਰਿਕਾਰਡ ਨੂੰ ਸਮਾਪਤ ਕਰਦੀ ਹੈ ਅਤੇ ਪਿਛਲਾ ਅਹੁਦਾ ਬਹਾਲ ਕਰਦੀ ਹੈ; ਇਤਿਹਾਸ ਦੋਵੇਂ ਰੱਖਦਾ ਹੈ।",
  "Reversible. Record a further org assignment to move the employee back.": "ਵਾਪਸੀਯੋਗ। ਕਰਮਚਾਰੀ ਨੂੰ ਵਾਪਸ ਭੇਜਣ ਲਈ ਇੱਕ ਹੋਰ ਸੰਗਠਨ ਸੌਂਪਣੀ ਦਰਜ ਕਰੋ।",
  "This is a one-way transition from probation to confirmed/active. Verify the employee and effective date before applying.": "ਇਹ ਪ੍ਰੋਬੇਸ਼ਨ ਤੋਂ ਪੱਕੇ/ਸਰਗਰਮ ਵਿੱਚ ਇੱਕ-ਪਾਸੜ ਤਬਦੀਲੀ ਹੈ। ਲਾਗੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਕਰਮਚਾਰੀ ਅਤੇ ਲਾਗੂ ਹੋਣ ਦੀ ਤਾਰੀਖ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।",
