  "You do not have permission to complete onboarding for this employee.": "ਤੁਹਾਨੂੰ ਇਸ ਕਰਮਚਾਰੀ ਦੀ ਆਨਬੋਰਡਿੰਗ ਪੂਰੀ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ।",
