  "Manager notes and calibrated ratings stay hidden until the outcome is published. Publishing an appraisal does not change pay, promotion or any other HR record.": "ਮੈਨੇਜਰ ਦੀਆਂ ਟਿੱਪਣੀਆਂ ਅਤੇ ਸੰਤੁਲਿਤ ਰੇਟਿੰਗਾਂ ਨਤੀਜਾ ਪ੍ਰਕਾਸ਼ਿਤ ਹੋਣ ਤੱਕ ਲੁਕੀਆਂ ਰਹਿੰਦੀਆਂ ਹਨ। ਕਾਰਗੁਜ਼ਾਰੀ ਸਮੀਖਿਆ ਪ੍ਰਕਾਸ਼ਿਤ ਕਰਨ ਨਾਲ ਤਨਖਾਹ, ਤਰੱਕੀ ਜਾਂ ਕੋਈ ਹੋਰ HR ਰਿਕਾਰਡ ਨਹੀਂ ਬਦਲਦਾ।",
