  "Bank detail: check it against the employee's passbook or a cancelled cheque before applying. The number is shown masked once decided.": "ਬੈਂਕ ਵੇਰਵਾ: ਲਾਗੂ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਇਸਨੂੰ ਕਰਮਚਾਰੀ ਦੀ ਪਾਸਬੁੱਕ ਜਾਂ ਰੱਦ ਕੀਤੇ ਚੈੱਕ ਨਾਲ ਮਿਲਾ ਕੇ ਵੇਖੋ। ਫ਼ੈਸਲੇ ਤੋਂ ਬਾਅਦ ਨੰਬਰ ਲੁਕਾ ਕੇ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।",
