  "This submits a formal resignation with a proposed last day of {lastDay} ({noticePeriodDays}-day notice) for HR approval.": "ਇਹ HR ਦੀ ਮਨਜ਼ੂਰੀ ਲਈ {lastDay} ਦੇ ਪ੍ਰਸਤਾਵਿਤ ਆਖ਼ਰੀ ਦਿਨ ({noticePeriodDays} ਦਿਨਾਂ ਦਾ ਨੋਟਿਸ) ਨਾਲ ਰਸਮੀ ਅਸਤੀਫ਼ਾ ਜਮ੍ਹਾਂ ਕਰਦਾ ਹੈ।",
  "Your proposed last day cannot be in the past.": "ਤੁਹਾਡਾ ਪ੍ਰਸਤਾਵਿਤ ਆਖ਼ਰੀ ਦਿਨ ਬੀਤੀ ਤਾਰੀਖ ਵਿੱਚ ਨਹੀਂ ਹੋ ਸਕਦਾ।",
  "I declare that the information given above is true and complete, and I will submit proofs when payroll asks for them.": "ਮੈਂ ਐਲਾਨ ਕਰਦਾ/ਕਰਦੀ ਹਾਂ ਕਿ ਉੱਪਰ ਦਿੱਤੀ ਜਾਣਕਾਰੀ ਸੱਚੀ ਅਤੇ ਪੂਰੀ ਹੈ, ਅਤੇ ਪੇਰੋਲ ਵੱਲੋਂ ਮੰਗਣ ਤੇ ਮੈਂ ਸਬੂਤ ਜਮ੍ਹਾਂ ਕਰਾਂਗਾ/ਕਰਾਂਗੀ।",
  "Loading form…": "ਫਾਰਮ ਲੋਡ ਹੋ ਰਿਹਾ ਹੈ…",
  "No investments or rent to declare under the new regime. Switch to the old regime if you want to claim deductions.": "ਨਵੀਂ ਪ੍ਰਣਾਲੀ ਅਧੀਨ ਘੋਸ਼ਿਤ ਕਰਨ ਲਈ ਕੋਈ ਨਿਵੇਸ਼ ਜਾਂ ਕਿਰਾਇਆ ਨਹੀਂ ਹੈ। ਜੇ ਤੁਸੀਂ ਕਟੌਤੀਆਂ ਦਾ ਦਾਅਵਾ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ ਤਾਂ ਪੁਰਾਣੀ ਪ੍ਰਣਾਲੀ ਤੇ ਜਾਓ।",
  "Please confirm that the information you have declared is correct.": "ਕਿਰਪਾ ਕਰਕੇ ਪੁਸ਼ਟੀ ਕਰੋ ਕਿ ਤੁਹਾਡੇ ਵੱਲੋਂ ਘੋਸ਼ਿਤ ਕੀਤੀ ਜਾਣਕਾਰੀ ਸਹੀ ਹੈ।",
  "Submit for review": "ਸਮੀਖਿਆ ਲਈ ਜਮ੍ਹਾਂ ਕਰੋ",
  "Tax declaration — FY {year}": "ਟੈਕਸ ਘੋਸ਼ਣਾ — ਵਿੱਤੀ ਸਾਲ {year}",
  "Tell payroll what you plan to claim this year so the right tax is deducted each month. You can submit the proofs (receipts, certificates) item by item on the Tax page after you submit.": "ਪੇਰੋਲ ਨੂੰ ਦੱਸੋ ਕਿ ਤੁਸੀਂ ਇਸ ਸਾਲ ਕੀ ਦਾਅਵਾ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ ਤਾਂ ਜੋ ਹਰ ਮਹੀਨੇ ਸਹੀ ਟੈਕਸ ਕੱਟਿਆ ਜਾਵੇ। ਜਮ੍ਹਾਂ ਕਰਨ ਤੋਂ ਬਾਅਦ ਤੁਸੀਂ ਟੈਕਸ ਪੰਨੇ ਤੇ ਸਬੂਤ (ਰਸੀਦਾਂ, ਸਰਟੀਫਿਕੇਟ) ਇੱਕ-ਇੱਕ ਕਰਕੇ ਜਮ੍ਹਾਂ ਕਰ ਸਕਦੇ ਹੋ।",
  "The form is still loading.": "ਫਾਰਮ ਹਾਲੇ ਲੋਡ ਹੋ ਰਿਹਾ ਹੈ।",
