  "I, my spouse or a child is a senior citizen (60+)": "ਮੈਂ, ਮੇਰਾ ਜੀਵਨ ਸਾਥੀ ਜਾਂ ਬੱਚਾ ਸੀਨੀਅਰ ਸਿਟੀਜ਼ਨ (60+) ਹੈ",
  "Lender's PAN": "ਕਰਜ਼ਾ ਦੇਣ ਵਾਲੇ ਦਾ PAN",
