  "Proof: {proof}": "ਸਬੂਤ: {proof}",
  " · Approved by {name}": " · {name} ਵੱਲੋਂ ਮਨਜ਼ੂਰ",
  "Choose your tax regime and declare your investments so the right tax is deducted from your salary.": "ਆਪਣੀ ਟੈਕਸ ਪ੍ਰਣਾਲੀ ਚੁਣੋ ਅਤੇ ਆਪਣੇ ਨਿਵੇਸ਼ ਘੋਸ਼ਿਤ ਕਰੋ ਤਾਂ ਜੋ ਤੁਹਾਡੀ ਤਨਖਾਹ ਵਿੱਚੋਂ ਸਹੀ ਟੈਕਸ ਕੱਟਿਆ ਜਾਵੇ।",
