  "New regime: only the standard deduction applies, so there is nothing else to claim.": "ਨਵੀਂ ਪ੍ਰਣਾਲੀ: ਸਿਰਫ਼ ਮਿਆਰੀ ਕਟੌਤੀ ਲਾਗੂ ਹੁੰਦੀ ਹੈ, ਇਸ ਲਈ ਹੋਰ ਕੁਝ ਦਾਅਵਾ ਕਰਨ ਲਈ ਨਹੀਂ ਹੈ।",
