  "No deductions declared yet.": "ਹਾਲੇ ਤੱਕ ਕੋਈ ਕਟੌਤੀ ਘੋਸ਼ਿਤ ਨਹੀਂ ਕੀਤੀ ਗਈ।",
  "Rent declared — your HRA exemption is worked out by payroll from your salary when it is processed.": "ਕਿਰਾਇਆ ਘੋਸ਼ਿਤ ਕੀਤਾ ਗਿਆ — ਤੁਹਾਡੀ HRA ਛੋਟ ਤਨਖਾਹ ਪ੍ਰੋਸੈਸ ਹੋਣ ਸਮੇਂ ਪੇਰੋਲ ਵੱਲੋਂ ਤੁਹਾਡੀ ਤਨਖਾਹ ਦੇ ਆਧਾਰ ਤੇ ਕੱਢੀ ਜਾਂਦੀ ਹੈ।",
  "Saved as a draft — not sent to payroll yet": "ਡਰਾਫਟ ਵਜੋਂ ਸੰਭਾਲਿਆ ਗਿਆ — ਹਾਲੇ ਪੇਰੋਲ ਨੂੰ ਨਹੀਂ ਭੇਜਿਆ ਗਿਆ",
  "Submitted {date}": "{date} ਨੂੰ ਜਮ੍ਹਾਂ ਕੀਤੀ",
  "Submitted declarations are reviewed by Payroll Operations. Proofs go under Documents → Tax proof.": "ਜਮ੍ਹਾਂ ਕੀਤੀਆਂ ਘੋਸ਼ਣਾਵਾਂ ਦੀ ਸਮੀਖਿਆ ਪੇਰੋਲ ਸੰਚਾਲਨ ਵੱਲੋਂ ਕੀਤੀ ਜਾਂਦੀ ਹੈ। ਸਬੂਤ ਦਸਤਾਵੇਜ਼ → ਟੈਕਸ ਸਬੂਤ ਵਿੱਚ ਜਾਂਦੇ ਹਨ।",
  "Total deduction after limits": "ਸੀਮਾਵਾਂ ਤੋਂ ਬਾਅਦ ਕੁੱਲ ਕਟੌਤੀ",
  "Approve this tax declaration?": "ਕੀ ਇਹ ਟੈਕਸ ਘੋਸ਼ਣਾ ਮਨਜ਼ੂਰ ਕਰਨੀ ਹੈ?",
  "Failed to approve this declaration. Please try again.": "ਇਹ ਘੋਸ਼ਣਾ ਮਨਜ਼ੂਰ ਨਹੀਂ ਹੋ ਸਕੀ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
