  "This locks {name}'s FY {year} declaration ({regime}, {deductions} deductions after limits) — they will no longer be able to change their regime or declared investments for this financial year.": "ਇਹ {name} ਦੀ ਵਿੱਤੀ ਸਾਲ {year} ਦੀ ਘੋਸ਼ਣਾ ({regime}, ਸੀਮਾਵਾਂ ਤੋਂ ਬਾਅਦ {deductions} ਕਟੌਤੀਆਂ) ਨੂੰ ਲੌਕ ਕਰ ਦੇਵੇਗਾ — ਉਹ ਇਸ ਵਿੱਤੀ ਸਾਲ ਲਈ ਆਪਣੀ ਪ੍ਰਣਾਲੀ ਜਾਂ ਘੋਸ਼ਿਤ ਨਿਵੇਸ਼ ਹੁਣ ਨਹੀਂ ਬਦਲ ਸਕਣਗੇ।",
