  "Joined this year? Enter what your previous employer paid you and the tax they deducted this financial year (from your Form 16 or last payslip). Leave blank if this is your first job this year.": "ਇਸ ਸਾਲ ਜੁਆਇਨ ਕੀਤਾ ਹੈ? ਇਸ ਵਿੱਤੀ ਸਾਲ ਵਿੱਚ ਤੁਹਾਡੇ ਪਿਛਲੇ ਮਾਲਕ ਨੇ ਤੁਹਾਨੂੰ ਜੋ ਦਿੱਤਾ ਅਤੇ ਜੋ ਟੈਕਸ ਕੱਟਿਆ, ਉਹ ਦਾਖਲ ਕਰੋ (ਤੁਹਾਡੇ ਫਾਰਮ 16 ਜਾਂ ਆਖ਼ਰੀ ਤਨਖਾਹ ਪਰਚੀ ਤੋਂ)। ਜੇ ਇਸ ਸਾਲ ਇਹ ਤੁਹਾਡੀ ਪਹਿਲੀ ਨੌਕਰੀ ਹੈ ਤਾਂ ਖਾਲੀ ਛੱਡੋ।",
