  "Only the old regime has deductions that need proof.": "ਸਿਰਫ਼ ਪੁਰਾਣੀ ਪ੍ਰਣਾਲੀ ਵਿੱਚ ਹੀ ਅਜਿਹੀਆਂ ਕਟੌਤੀਆਂ ਹਨ ਜਿਨ੍ਹਾਂ ਲਈ ਸਬੂਤ ਚਾਹੀਦਾ ਹੈ।",
  "Upload": "ਅੱਪਲੋਡ ਕਰੋ",
  "Upload a receipt or certificate for each item you claimed. Payroll verifies them before they count in full.": "ਜਿਸ ਮੱਦ ਦਾ ਤੁਸੀਂ ਦਾਅਵਾ ਕੀਤਾ ਉਸ ਲਈ ਰਸੀਦ ਜਾਂ ਸਰਟੀਫਿਕੇਟ ਅੱਪਲੋਡ ਕਰੋ। ਪੂਰੇ ਗਿਣੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਪੇਰੋਲ ਇਨ੍ਹਾਂ ਦੀ ਪੁਸ਼ਟੀ ਕਰਦਾ ਹੈ।",
