  "Viewing this employee's workspace — read-only. Nothing you do here is saved.": "ਇਸ ਕਰਮਚਾਰੀ ਦਾ ਵਰਕਸਪੇਸ ਵੇਖ ਰਹੇ ਹੋ — ਸਿਰਫ਼ ਪੜ੍ਹਨ ਲਈ। ਇੱਥੇ ਤੁਸੀਂ ਜੋ ਵੀ ਕਰੋ ਉਹ ਸੰਭਾਲਿਆ ਨਹੀਂ ਜਾਂਦਾ।",
