  "PDF, JPG or PNG, up to 5 MB each. At least one is required.": "PDF, JPG ਜਾਂ PNG, ਹਰੇਕ ਵੱਧ ਤੋਂ ਵੱਧ 5 MB। ਘੱਟੋ-ਘੱਟ ਇੱਕ ਲੋੜੀਂਦੀ ਹੈ।",
