  "PDF, JPG, PNG up to 5 MB each — at least one required": "PDF, JPG, PNG ਹਰੇਕ ਵੱਧ ਤੋਂ ਵੱਧ 5 MB — ਘੱਟੋ-ਘੱਟ ਇੱਕ ਲੋੜੀਂਦੀ",
