  "Step {number}: {title}. Go to the employee search": "ਕਦਮ {number}: {title}। ਕਰਮਚਾਰੀ ਖੋਜ ਤੇ ਜਾਓ",
  "Step {number}: {title}. Locked until an employee is chosen": "ਕਦਮ {number}: {title}। ਕਰਮਚਾਰੀ ਚੁਣਨ ਤੱਕ ਲੌਕ ਹੈ",
  "This employee has not registered a Face ID. You can register it now, in person.": "ਇਸ ਕਰਮਚਾਰੀ ਨੇ Face ID ਰਜਿਸਟਰ ਨਹੀਂ ਕੀਤੀ ਹੈ। ਤੁਸੀਂ ਇਸਨੂੰ ਹੁਣ ਵਿਅਕਤੀਗਤ ਤੌਰ ਤੇ ਰਜਿਸਟਰ ਕਰ ਸਕਦੇ ਹੋ।",
  "This will replace {name}'s registered Face ID will be replaced by the new capture.": "ਇਹ {name} ਦੀ ਰਜਿਸਟਰ ਕੀਤੀ Face ID ਨੂੰ ਨਵੀਂ ਕੈਪਚਰ ਨਾਲ ਬਦਲ ਦੇਵੇਗਾ।",
