  "Search employees by name, email or ID": "ਕਰਮਚਾਰੀਆਂ ਨੂੰ ਨਾਮ, ਈਮੇਲ ਜਾਂ ID ਨਾਲ ਖੋਜੋ",
  "{percent}% registered": "{percent}% ਰਜਿਸਟਰ",
  "Everyone is registered": "ਸਾਰੇ ਰਜਿਸਟਰ ਹੋ ਚੁੱਕੇ ਹਨ",
  "Face ID coverage": "Face ID ਕਵਰੇਜ",
  "Filter employees by Face ID status": "ਕਰਮਚਾਰੀਆਂ ਨੂੰ Face ID ਦੀ ਸਥਿਤੀ ਅਨੁਸਾਰ ਫਿਲਟਰ ਕਰੋ",
  "of {total} employees registered": "{total} ਕਰਮਚਾਰੀਆਂ ਵਿੱਚੋਂ ਰਜਿਸਟਰ",
  "Show {count} not completed": "{count} ਅਧੂਰੇ ਦਿਖਾਓ",
  "Pending requests": "ਬਾਕੀ ਬੇਨਤੀਆਂ",
  "Register or update an employee's Face ID in person. It is approved immediately.": "ਕਰਮਚਾਰੀ ਦੀ Face ID ਵਿਅਕਤੀਗਤ ਤੌਰ ਤੇ ਰਜਿਸਟਰ ਜਾਂ ਅੱਪਡੇਟ ਕਰੋ। ਇਹ ਤੁਰੰਤ ਮਨਜ਼ੂਰ ਹੋ ਜਾਂਦੀ ਹੈ।",
  "{name}'s face ID is approved and active immediately — no further review needed.": "{name} ਦੀ Face ID ਤੁਰੰਤ ਮਨਜ਼ੂਰ ਅਤੇ ਸਰਗਰਮ ਹੋ ਜਾਂਦੀ ਹੈ — ਹੋਰ ਸਮੀਖਿਆ ਦੀ ਲੋੜ ਨਹੀਂ।",
  "Camera access denied": "ਕੈਮਰਾ ਐਕਸੈਸ ਤੋਂ ਇਨਕਾਰ",
  "Capture wasn't clear enough": "ਕੈਪਚਰ ਕਾਫ਼ੀ ਸਾਫ਼ ਨਹੀਂ ਸੀ",
  "Couldn't confirm they're live": "ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋ ਸਕੀ ਕਿ ਵਿਅਕਤੀ ਅਸਲੀ ਹੈ",
  "Downloading face models (first time only)…": "ਚਿਹਰੇ ਦੇ ਮਾਡਲ ਡਾਊਨਲੋਡ ਹੋ ਰਹੇ ਹਨ (ਸਿਰਫ਼ ਪਹਿਲੀ ਵਾਰ)…",
  "Face ID registered!": "Face ID ਰਜਿਸਟਰ ਹੋ ਗਈ!",
  "Have the employee sit in front of this camera, then start — a quick liveness check confirms it's really them before it's saved.": "ਕਰਮਚਾਰੀ ਨੂੰ ਇਸ ਕੈਮਰੇ ਦੇ ਸਾਹਮਣੇ ਬਿਠਾਓ, ਫਿਰ ਸ਼ੁਰੂ ਕਰੋ — ਸੰਭਾਲਣ ਤੋਂ ਪਹਿਲਾਂ ਇੱਕ ਛੋਟੀ ਲਾਈਵਨੈੱਸ ਜਾਂਚ ਪੁਸ਼ਟੀ ਕਰਦੀ ਹੈ ਕਿ ਇਹ ਅਸਲ ਵਿੱਚ ਉਹੀ ਹਨ।",
  "Please allow camera access in the browser prompt.": "ਕਿਰਪਾ ਕਰਕੇ ਬ੍ਰਾਊਜ਼ਰ ਦੇ ਸੁਨੇਹੇ ਵਿੱਚ ਕੈਮਰਾ ਐਕਸੈਸ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ।",
  "Please try again.": "ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Preparing face recognition": "ਚਿਹਰਾ ਪਛਾਣ ਤਿਆਰ ਹੋ ਰਹੀ ਹੈ",
  "Register {name}'s face": "{name} ਦਾ ਚਿਹਰਾ ਰਜਿਸਟਰ ਕਰੋ",
  "Register Face ID — {name}": "Face ID ਰਜਿਸਟਰ ਕਰੋ — {name}",
  "Registering a face ID needs camera access. Allow it for this site in your browser's settings, then try again.": "Face ID ਰਜਿਸਟਰ ਕਰਨ ਲਈ ਕੈਮਰਾ ਐਕਸੈਸ ਚਾਹੀਦਾ ਹੈ। ਆਪਣੇ ਬ੍ਰਾਊਜ਼ਰ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਇਸ ਸਾਈਟ ਲਈ ਇਸਦੀ ਇਜਾਜ਼ਤ ਦਿਓ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Registering face ID…": "Face ID ਰਜਿਸਟਰ ਹੋ ਰਹੀ ਹੈ…",
  "Registration needs both a natural blink and a slight head turn, and we didn't see both in time. Make sure they're well-lit and centered, then try again.": "ਰਜਿਸਟ੍ਰੇਸ਼ਨ ਲਈ ਕੁਦਰਤੀ ਝਪਕ ਅਤੇ ਸਿਰ ਦਾ ਹਲਕਾ ਮੋੜ ਦੋਵੇਂ ਚਾਹੀਦੇ ਹਨ, ਅਤੇ ਅਸੀਂ ਸਮੇਂ ਸਿਰ ਦੋਵੇਂ ਨਹੀਂ ਵੇਖੇ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਰੋਸ਼ਨੀ ਚੰਗੀ ਹੈ ਅਤੇ ਚਿਹਰਾ ਵਿਚਕਾਰ ਹੈ, ਫਿਰ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Requesting camera access": "ਕੈਮਰਾ ਐਕਸੈਸ ਮੰਗਿਆ ਜਾ ਰਿਹਾ ਹੈ",
  "Saving": "ਸੰਭਾਲਿਆ ਜਾ ਰਿਹਾ ਹੈ",
  "Something went wrong": "ਕੁਝ ਗਲਤ ਹੋ ਗਿਆ",
  "This will replace their currently registered face ID. Position them in front of the camera and start when ready.": "ਇਹ ਉਨ੍ਹਾਂ ਦੀ ਮੌਜੂਦਾ ਰਜਿਸਟਰ ਕੀਤੀ Face ID ਨੂੰ ਬਦਲ ਦੇਵੇਗਾ। ਉਨ੍ਹਾਂ ਨੂੰ ਕੈਮਰੇ ਦੇ ਸਾਹਮਣੇ ਬਿਠਾਓ ਅਤੇ ਤਿਆਰ ਹੋਣ ਤੇ ਸ਼ੁਰੂ ਕਰੋ।",
  "Try Again": "ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ",
  "Update {name}'s face": "{name} ਦਾ ਚਿਹਰਾ ਅੱਪਡੇਟ ਕਰੋ",
  "Update Face ID — {name}": "Face ID ਅੱਪਡੇਟ ਕਰੋ — {name}",
  "We couldn't get a reliably clear capture — this becomes their permanent face ID reference, so it's worth getting right. Try better lighting and have them hold steady.": "ਸਾਨੂੰ ਭਰੋਸੇਯੋਗ ਸਾਫ਼ ਕੈਪਚਰ ਨਹੀਂ ਮਿਲਿਆ — ਇਹ ਉਨ੍ਹਾਂ ਦੀ ਪੱਕੀ Face ID ਦਾ ਹਵਾਲਾ ਬਣਦਾ ਹੈ, ਇਸ ਲਈ ਇਸਦਾ ਸਹੀ ਹੋਣਾ ਜ਼ਰੂਰੀ ਹੈ। ਬਿਹਤਰ ਰੋਸ਼ਨੀ ਵਿੱਚ ਕੋਸ਼ਿਸ਼ ਕਰੋ ਅਤੇ ਉਨ੍ਹਾਂ ਨੂੰ ਸਥਿਰ ਰਹਿਣ ਲਈ ਕਹੋ।",
  "Contact an HR administrator if you believe this is a mistake.": "ਜੇ ਤੁਹਾਨੂੰ ਲੱਗਦਾ ਹੈ ਕਿ ਇਹ ਗਲਤੀ ਹੈ ਤਾਂ HR ਐਡਮਿਨਿਸਟ੍ਰੇਟਰ ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "You don't have permission to manage face ID registrations": "ਤੁਹਾਨੂੰ Face ID ਰਜਿਸਟ੍ਰੇਸ਼ਨਾਂ ਦਾ ਪ੍ਰਬੰਧ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਨਹੀਂ ਹੈ",
  "{count} PIN codes in {district}": "{district} ਵਿੱਚ {count} ਪਿੰਨ ਕੋਡ",
  "Address line 1": "ਪਤਾ ਲਾਈਨ 1",
  "Address line 2": "ਪਤਾ ਲਾਈਨ 2",
  "Already filled in from the PIN code": "ਪਿੰਨ ਕੋਡ ਤੋਂ ਪਹਿਲਾਂ ਹੀ ਭਰਿਆ ਗਿਆ",
  "Country": "ਦੇਸ਼",
  "CURRENT ADDRESS": "ਮੌਜੂਦਾ ਪਤਾ",
  "Enter the 6-digit PIN code first. Suggest fills the state, district and city from it. You can also choose the state, then the district, then pick the PIN code from the list.": "ਪਹਿਲਾਂ 6 ਅੰਕਾਂ ਦਾ ਪਿੰਨ ਕੋਡ ਦਾਖਲ ਕਰੋ। \"ਸੁਝਾਓ\" ਉਸ ਤੋਂ ਰਾਜ, ਜ਼ਿਲ੍ਹਾ ਅਤੇ ਸ਼ਹਿਰ ਭਰ ਦਿੰਦਾ ਹੈ। ਤੁਸੀਂ ਰਾਜ, ਫਿਰ ਜ਼ਿਲ੍ਹਾ ਚੁਣ ਕੇ ਸੂਚੀ ਵਿੱਚੋਂ ਪਿੰਨ ਕੋਡ ਵੀ ਚੁਣ ਸਕਦੇ ਹੋ।",
  "Fill this in from the PIN code": "ਇਸਨੂੰ ਪਿੰਨ ਕੋਡ ਤੋਂ ਭਰੋ",
  "Filled": "ਭਰਿਆ ਗਿਆ",
