  "Suggest": "ਸੁਝਾਓ",
  "That PIN code has no area name to suggest. Type the city.": "ਉਸ ਪਿੰਨ ਕੋਡ ਲਈ ਸੁਝਾਉਣ ਵਾਸਤੇ ਕੋਈ ਇਲਾਕੇ ਦਾ ਨਾਮ ਨਹੀਂ ਹੈ। ਸ਼ਹਿਰ ਲਿਖੋ।",
  "We could not find PIN code {pincode}. Check it, or choose the state and district yourself.": "ਸਾਨੂੰ ਪਿੰਨ ਕੋਡ {pincode} ਨਹੀਂ ਮਿਲਿਆ। ਇਸਨੂੰ ਜਾਂਚੋ, ਜਾਂ ਰਾਜ ਅਤੇ ਜ਼ਿਲ੍ਹਾ ਆਪ ਚੁਣੋ।",
