  "The new hire cannot register it themselves.": "ਨਵਾਂ ਭਰਤੀ ਕੀਤਾ ਕਰਮਚਾਰੀ ਇਸਨੂੰ ਆਪ ਰਜਿਸਟਰ ਨਹੀਂ ਕਰ ਸਕਦਾ।",
  "The new hire registers their Face ID from their Profile page, and HR approves it on": "ਨਵਾਂ ਭਰਤੀ ਕੀਤਾ ਕਰਮਚਾਰੀ ਆਪਣੇ ਪ੍ਰੋਫਾਈਲ ਪੰਨੇ ਤੋਂ Face ID ਰਜਿਸਟਰ ਕਰਦਾ ਹੈ, ਅਤੇ HR ਇਸਨੂੰ ਇੱਥੇ ਮਨਜ਼ੂਰ ਕਰਦਾ ਹੈ:",
  "The new hire registers their own Face ID from their Profile page; it is active immediately.": "ਨਵਾਂ ਭਰਤੀ ਕੀਤਾ ਕਰਮਚਾਰੀ ਆਪਣੇ ਪ੍ਰੋਫਾਈਲ ਪੰਨੇ ਤੋਂ ਆਪਣੀ Face ID ਆਪ ਰਜਿਸਟਰ ਕਰਦਾ ਹੈ; ਇਹ ਤੁਰੰਤ ਸਰਗਰਮ ਹੋ ਜਾਂਦੀ ਹੈ।",
  "the record can still be created in Onboarding status.": "ਰਿਕਾਰਡ ਫਿਰ ਵੀ ਆਨਬੋਰਡਿੰਗ ਸਥਿਤੀ ਵਿੱਚ ਬਣਾਇਆ ਜਾ ਸਕਦਾ ਹੈ।",
  "The record is created in Onboarding status. Optional details (father/mother's name, non-required documents) can still be finished afterward.": "ਰਿਕਾਰਡ ਆਨਬੋਰਡਿੰਗ ਸਥਿਤੀ ਵਿੱਚ ਬਣਾਇਆ ਜਾਂਦਾ ਹੈ। ਵਿਕਲਪਿਕ ਵੇਰਵੇ (ਪਿਤਾ/ਮਾਤਾ ਦਾ ਨਾਮ, ਗ਼ੈਰ-ਲੋੜੀਂਦੇ ਦਸਤਾਵੇਜ਼) ਬਾਅਦ ਵਿੱਚ ਵੀ ਪੂਰੇ ਕੀਤੇ ਜਾ ਸਕਦੇ ਹਨ।",
  "Until it is done they cannot clock in on the web.": "ਇਹ ਹੋਣ ਤੱਕ ਉਹ ਵੈੱਬ ਤੇ ਕਲੌਕ-ਇਨ ਨਹੀਂ ਕਰ ਸਕਦੇ।",
  "Until then they can still clock in from the office; those punches are flagged for HR.": "ਉਦੋਂ ਤੱਕ ਉਹ ਦਫ਼ਤਰ ਤੋਂ ਕਲੌਕ-ਇਨ ਕਰ ਸਕਦੇ ਹਨ; ਉਨ੍ਹਾਂ ਪੰਚਾਂ ਨੂੰ HR ਲਈ ਚਿੰਨ੍ਹਿਤ ਕੀਤਾ ਜਾਂਦਾ ਹੈ।",
  "Apply selected": "ਚੁਣੇ ਹੋਏ ਲਾਗੂ ਕਰੋ",
