  "FOUND IN DOCUMENT": "ਦਸਤਾਵੇਜ਼ ਵਿੱਚ ਮਿਲਿਆ",
  "Scanning…": "ਸਕੈਨ ਹੋ ਰਿਹਾ ਹੈ…",
  "Upload a text-based PDF (an offer letter, ID or resume exported as PDF). This reads the actual text in the document and matches recognizable fields — it does not guess anything not on the page.": "ਟੈਕਸਟ ਵਾਲੀ PDF ਅੱਪਲੋਡ ਕਰੋ (PDF ਵਜੋਂ ਨਿਰਯਾਤ ਕੀਤਾ ਆਫ਼ਰ ਲੈਟਰ, ID ਜਾਂ ਰੈਜ਼ਿਊਮੇ)। ਇਹ ਦਸਤਾਵੇਜ਼ ਵਿੱਚ ਅਸਲ ਟੈਕਸਟ ਪੜ੍ਹਦਾ ਹੈ ਅਤੇ ਪਛਾਣੇ ਜਾ ਸਕਣ ਵਾਲੇ ਖੇਤਰ ਮਿਲਾਉਂਦਾ ਹੈ — ਜੋ ਪੰਨੇ ਤੇ ਨਹੀਂ ਹੈ ਉਸਦਾ ਅੰਦਾਜ਼ਾ ਨਹੀਂ ਲਾਉਂਦਾ।",
