  "Placing a person on a chief position makes them the unit's head automatically, as of the effective date above. A future-dated start schedules the change without affecting today's holder.": "ਕਿਸੇ ਵਿਅਕਤੀ ਨੂੰ ਮੁਖੀ ਦੇ ਅਹੁਦੇ ਤੇ ਰੱਖਣ ਨਾਲ ਉਹ ਉੱਪਰ ਦਿੱਤੀ ਲਾਗੂ ਮਿਤੀ ਤੋਂ ਆਪਣੇ-ਆਪ ਇਕਾਈ ਦਾ ਮੁਖੀ ਬਣ ਜਾਂਦਾ ਹੈ। ਭਵਿੱਖ ਦੀ ਸ਼ੁਰੂ ਤਾਰੀਖ ਤਬਦੀਲੀ ਨੂੰ ਤੈਅ ਕਰ ਦਿੰਦੀ ਹੈ ਅਤੇ ਅੱਜ ਦੇ ਧਾਰਕ ਤੇ ਕੋਈ ਅਸਰ ਨਹੀਂ ਪੈਂਦਾ।",
