  "end their placement or vacate the seat — the position will just show as": "ਉਨ੍ਹਾਂ ਦੀ ਨਿਯੁਕਤੀ ਖਤਮ ਨਹੀਂ ਕਰਦਾ ਜਾਂ ਸੀਟ ਖਾਲੀ ਨਹੀਂ ਕਰਦਾ — ਅਹੁਦਾ ਸਿਰਫ਼ ਇਸ ਵਜੋਂ ਦਿਖੇਗਾ:",
