  "Positions with nobody reporting to them and no one they report to. Set 'Reports to' on a position to place it in the chain.": "ਉਹ ਅਹੁਦੇ ਜਿਨ੍ਹਾਂ ਨੂੰ ਕੋਈ ਰਿਪੋਰਟ ਨਹੀਂ ਕਰਦਾ ਅਤੇ ਜੋ ਕਿਸੇ ਨੂੰ ਰਿਪੋਰਟ ਨਹੀਂ ਕਰਦੇ। ਕਿਸੇ ਅਹੁਦੇ ਨੂੰ ਲੜੀ ਵਿੱਚ ਰੱਖਣ ਲਈ ਉਸ ਉੱਤੇ \"ਰਿਪੋਰਟ ਕਰਦਾ ਹੈ\" ਸੈੱਟ ਕਰੋ।",
