  "; whoever holds it is the head. The seat can stay": "; ਜੋ ਵੀ ਇਸ ਉੱਤੇ ਹੋਵੇ ਉਹੀ ਮੁਖੀ ਹੈ। ਇਹ ਸੀਟ ਖਾਲੀ ਰਹਿ ਸਕਦੀ ਹੈ",
  ". Access belongs to that seat—not the reporting chain; employees sharing a seat share its permissions. Use separate positions when employees need different access.": "। ਪਹੁੰਚ ਉਸ ਸੀਟ ਦੀ ਹੁੰਦੀ ਹੈ—ਰਿਪੋਰਟਿੰਗ ਲੜੀ ਦੀ ਨਹੀਂ; ਇੱਕ ਸੀਟ ਸਾਂਝੀ ਕਰਨ ਵਾਲੇ ਕਰਮਚਾਰੀ ਉਸ ਦੀਆਂ ਇਜਾਜ਼ਤਾਂ ਸਾਂਝੀਆਂ ਕਰਦੇ ਹਨ। ਜਦੋਂ ਕਰਮਚਾਰੀਆਂ ਨੂੰ ਵੱਖ-ਵੱਖ ਪਹੁੰਚ ਚਾਹੀਦੀ ਹੋਵੇ ਤਾਂ ਵੱਖਰੇ ਅਹੁਦੇ ਵਰਤੋ।",
