  "Marks this position as a team manager for manager-based workflows.": "ਮੈਨੇਜਰ-ਆਧਾਰਿਤ ਵਰਕਫਲੋ ਲਈ ਇਸ ਅਹੁਦੇ ਨੂੰ ਟੀਮ ਮੈਨੇਜਰ ਵਜੋਂ ਨਿਸ਼ਾਨਬੱਧ ਕਰਦਾ ਹੈ।",
