  "Team manager": "ਟੀਮ ਮੈਨੇਜਰ",
  "These permissions belong to this position. The current holder receives them; a future holder receives the same access. Permissions do not automatically pass between a manager and their reports. Give each position its own access below.": "ਇਹ ਇਜਾਜ਼ਤਾਂ ਇਸ ਅਹੁਦੇ ਦੀਆਂ ਹਨ। ਮੌਜੂਦਾ ਧਾਰਕ ਨੂੰ ਇਹ ਮਿਲਦੀਆਂ ਹਨ; ਭਵਿੱਖ ਦੇ ਧਾਰਕ ਨੂੰ ਵੀ ਇਹੀ ਪਹੁੰਚ ਮਿਲੇਗੀ। ਇਜਾਜ਼ਤਾਂ ਮੈਨੇਜਰ ਅਤੇ ਉਸ ਦੇ ਅਧੀਨ ਕਰਮਚਾਰੀਆਂ ਵਿਚਕਾਰ ਆਪਣੇ-ਆਪ ਨਹੀਂ ਜਾਂਦੀਆਂ। ਹਰ ਅਹੁਦੇ ਨੂੰ ਹੇਠਾਂ ਉਸ ਦੀ ਆਪਣੀ ਪਹੁੰਚ ਦਿਓ।",
  "Turning on Team manager also checked the usual manager permissions below (View employees, Approve leave, View attendance) so this position isn't left with 0 permissions. Uncheck any you don't want before saving.": "ਟੀਮ ਮੈਨੇਜਰ ਚਾਲੂ ਕਰਨ ਨਾਲ ਹੇਠਾਂ ਦੀਆਂ ਆਮ ਮੈਨੇਜਰ ਇਜਾਜ਼ਤਾਂ (ਕਰਮਚਾਰੀ ਵੇਖੋ, ਛੁੱਟੀ ਮਨਜ਼ੂਰ ਕਰੋ, ਹਾਜ਼ਰੀ ਵੇਖੋ) ਵੀ ਚੁਣ ਲਈਆਂ ਗਈਆਂ ਹਨ ਤਾਂ ਜੋ ਇਸ ਅਹੁਦੇ ਕੋਲ 0 ਇਜਾਜ਼ਤਾਂ ਨਾ ਰਹਿਣ। ਸੰਭਾਲਣ ਤੋਂ ਪਹਿਲਾਂ ਜੋ ਨਾ ਚਾਹੀਦੀਆਂ ਹੋਣ ਉਨ੍ਹਾਂ ਦੀ ਚੋਣ ਹਟਾ ਦਿਓ।",
