  "All {count} manager(s) have approved.": "ਸਾਰੇ {count} ਮੈਨੇਜਰਾਂ ਨੇ ਮਨਜ਼ੂਰੀ ਦੇ ਦਿੱਤੀ ਹੈ।",
  "All approvals complete. You can now proceed to compute payroll.": "ਸਾਰੀਆਂ ਮਨਜ਼ੂਰੀਆਂ ਪੂਰੀਆਂ ਹਨ। ਹੁਣ ਤੁਸੀਂ ਪੇਰੋਲ ਦੀ ਗਣਨਾ ਵੱਲ ਵਧ ਸਕਦੇ ਹੋ।",
  "Approval happens on the Team Approvals page, not here — go to": "ਮਨਜ਼ੂਰੀ ਟੀਮ ਮਨਜ਼ੂਰੀਆਂ ਪੰਨੇ ਤੇ ਹੁੰਦੀ ਹੈ, ਇੱਥੇ ਨਹੀਂ — ਇੱਥੇ ਜਾਓ:",
