  "Each manager must sign off on their team's attendance": "ਹਰ ਮੈਨੇਜਰ ਨੂੰ ਆਪਣੀ ਟੀਮ ਦੀ ਹਾਜ਼ਰੀ ਤੇ ਦਸਤਖ਼ਤ ਕਰਨੇ ਲਾਜ਼ਮੀ ਹਨ",
  "HR Approval (L2)": "HR ਮਨਜ਼ੂਰੀ (L2)",
  "HR Ops → Approvals → Attendance Approval": "HR ਸੰਚਾਲਨ → ਮਨਜ਼ੂਰੀਆਂ → ਹਾਜ਼ਰੀ ਮਨਜ਼ੂਰੀ",
  "HR sign-off is the final step before payroll can be processed.": "HR ਦੀ ਮਨਜ਼ੂਰੀ ਪੇਰੋਲ ਪ੍ਰੋਸੈਸ ਹੋਣ ਤੋਂ ਪਹਿਲਾਂ ਦਾ ਆਖ਼ਰੀ ਕਦਮ ਹੈ।",
  "HR verifies and signs off — unlocks payroll processing": "HR ਜਾਂਚ ਕਰਕੇ ਮਨਜ਼ੂਰੀ ਦਿੰਦਾ ਹੈ — ਪੇਰੋਲ ਪ੍ਰੋਸੈਸਿੰਗ ਖੁੱਲ੍ਹਦੀ ਹੈ",
