  "Manager Approval (L1)": "ਮੈਨੇਜਰ ਮਨਜ਼ੂਰੀ (L1)",
  "No managers with team management rights are configured — HR can approve directly.": "ਟੀਮ ਪ੍ਰਬੰਧਨ ਅਧਿਕਾਰਾਂ ਵਾਲਾ ਕੋਈ ਮੈਨੇਜਰ ਸੈੱਟ ਨਹੀਂ ਹੈ — HR ਸਿੱਧੇ ਮਨਜ਼ੂਰੀ ਦੇ ਸਕਦਾ ਹੈ।",
