  "Waiting for all managers (L1) to approve first": "ਪਹਿਲਾਂ ਸਾਰੇ ਮੈਨੇਜਰਾਂ (L1) ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਹੈ",
  "Waiting for HR to sign off from": "HR ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਹੈ, ਇੱਥੋਂ:",
  "Waiting for HR/Admin to complete the L1 step directly — no managers are configured for this cycle.": "HR/ਐਡਮਿਨ ਦੁਆਰਾ L1 ਕਦਮ ਸਿੱਧਾ ਪੂਰਾ ਕਰਨ ਦੀ ਉਡੀਕ ਹੈ — ਇਸ ਚੱਕਰ ਲਈ ਕੋਈ ਮੈਨੇਜਰ ਸੈੱਟ ਨਹੀਂ ਹੈ।",
  "Waiting for other managers to approve. Refresh to check latest status.": "ਹੋਰ ਮੈਨੇਜਰਾਂ ਦੀ ਮਨਜ਼ੂਰੀ ਦੀ ਉਡੀਕ ਹੈ। ਨਵੀਨਤਮ ਸਥਿਤੀ ਵੇਖਣ ਲਈ ਰੀਫ੍ਰੈਸ਼ ਕਰੋ।",
  "Your sign-off is required — approve it from": "ਤੁਹਾਡੀ ਮਨਜ਼ੂਰੀ ਲੋੜੀਂਦੀ ਹੈ — ਇੱਥੋਂ ਮਨਜ਼ੂਰ ਕਰੋ:",
  "{amount} total": "ਕੁੱਲ {amount}",
  "All salaries marked as paid. Payroll run for this cycle is complete.": "ਸਾਰੀਆਂ ਤਨਖਾਹਾਂ ਭੁਗਤਾਨ ਹੋਈਆਂ ਵਜੋਂ ਦਰਜ ਹਨ। ਇਸ ਚੱਕਰ ਦਾ ਪੇਰੋਲ ਰਨ ਪੂਰਾ ਹੋ ਗਿਆ ਹੈ।",
  "Checking salary transfer readiness…": "ਤਨਖਾਹ ਟ੍ਰਾਂਸਫਰ ਦੀ ਤਿਆਰੀ ਦੀ ਜਾਂਚ ਹੋ ਰਹੀ ਹੈ…",
  "Confirm and Lock": "ਪੁਸ਼ਟੀ ਕਰੋ ਅਤੇ ਲੌਕ ਕਰੋ",
  "Confirm Salary Transfer": "ਤਨਖਾਹ ਟ੍ਰਾਂਸਫਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ",
  "Confirm salary transfer?": "ਕੀ ਤਨਖਾਹ ਟ੍ਰਾਂਸਫਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰਨੀ ਹੈ?",
  "Download NEFT CSV": "NEFT CSV ਡਾਊਨਲੋਡ ਕਰੋ",
  "Employees have acknowledged their payslips. Confirm the salary transfer to lock bank details and generate the NEFT CSV.": "ਕਰਮਚਾਰੀਆਂ ਨੇ ਆਪਣੀਆਂ ਤਨਖਾਹ ਪਰਚੀਆਂ ਸਵੀਕਾਰ ਕਰ ਲਈਆਂ ਹਨ। ਬੈਂਕ ਵੇਰਵੇ ਲੌਕ ਕਰਨ ਅਤੇ NEFT CSV ਬਣਾਉਣ ਲਈ ਤਨਖਾਹ ਟ੍ਰਾਂਸਫਰ ਦੀ ਪੁਸ਼ਟੀ ਕਰੋ।",
  "Failed to confirm the salary transfer.": "ਤਨਖਾਹ ਟ੍ਰਾਂਸਫਰ ਦੀ ਪੁਸ਼ਟੀ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Failed to download the bank transfer file.": "ਬੈਂਕ ਟ੍ਰਾਂਸਫਰ ਫਾਈਲ ਡਾਊਨਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Failed to mark as paid.": "ਭੁਗਤਾਨ ਹੋਇਆ ਵਜੋਂ ਦਰਜ ਨਹੀਂ ਹੋ ਸਕਿਆ।",
  "Finish Payroll Run": "ਪੇਰੋਲ ਰਨ ਪੂਰਾ ਕਰੋ",
  "Gross − all deductions": "ਕੁੱਲ − ਸਾਰੀਆਂ ਕਟੌਤੀਆਂ",
  "In this payroll run": "ਇਸ ਪੇਰੋਲ ਰਨ ਵਿੱਚ",
  "Locking Transfer…": "ਟ੍ਰਾਂਸਫਰ ਲੌਕ ਹੋ ਰਿਹਾ ਹੈ…",
  "Mark All Paid": "ਸਾਰੀਆਂ ਨੂੰ ਭੁਗਤਾਨ ਹੋਇਆ ਦਰਜ ਕਰੋ",
  "Mark Payroll as Paid": "ਪੇਰੋਲ ਨੂੰ ਭੁਗਤਾਨ ਹੋਇਆ ਦਰਜ ਕਰੋ",
  "Mark payroll as paid?": "ਕੀ ਪੇਰੋਲ ਨੂੰ ਭੁਗਤਾਨ ਹੋਇਆ ਦਰਜ ਕਰਨਾ ਹੈ?",
  "Marking Paid…": "ਭੁਗਤਾਨ ਦਰਜ ਹੋ ਰਿਹਾ ਹੈ…",
  "Net Salary": "ਸ਼ੁੱਧ ਤਨਖਾਹ",
  "Paid": "ਭੁਗਤਾਨ ਹੋਇਆ",
  "Preparing CSV…": "CSV ਤਿਆਰ ਹੋ ਰਹੀ ਹੈ…",
  "Salary transfer locked for {count} employee(s). Download the NEFT CSV and submit it to your bank before marking payroll paid.": "{count} ਕਰਮਚਾਰੀਆਂ ਲਈ ਤਨਖਾਹ ਟ੍ਰਾਂਸਫਰ ਲੌਕ ਹੋ ਗਿਆ ਹੈ। ਪੇਰੋਲ ਨੂੰ ਭੁਗਤਾਨ ਹੋਇਆ ਦਰਜ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ NEFT CSV ਡਾਊਨਲੋਡ ਕਰੋ ਅਤੇ ਆਪਣੇ ਬੈਂਕ ਨੂੰ ਜਮ੍ਹਾਂ ਕਰੋ।",
  "Salary transfer readiness is unavailable.": "ਤਨਖਾਹ ਟ੍ਰਾਂਸਫਰ ਦੀ ਤਿਆਰੀ ਦੀ ਜਾਣਕਾਰੀ ਉਪਲਬਧ ਨਹੀਂ ਹੈ।",
  "This locks the current bank details and net pay for all {count} employee(s) into a transfer batch. Download the NEFT CSV after confirmation and submit it through your bank before marking payroll paid.": "ਇਹ ਸਾਰੇ {count} ਕਰਮਚਾਰੀਆਂ ਦੇ ਮੌਜੂਦਾ ਬੈਂਕ ਵੇਰਵੇ ਅਤੇ ਸ਼ੁੱਧ ਤਨਖਾਹ ਨੂੰ ਇੱਕ ਟ੍ਰਾਂਸਫਰ ਬੈਚ ਵਿੱਚ ਲੌਕ ਕਰ ਦਿੰਦਾ ਹੈ। ਪੁਸ਼ਟੀ ਤੋਂ ਬਾਅਦ NEFT CSV ਡਾਊਨਲੋਡ ਕਰੋ ਅਤੇ ਪੇਰੋਲ ਨੂੰ ਭੁਗਤਾਨ ਹੋਇਆ ਦਰਜ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣੇ ਬੈਂਕ ਰਾਹੀਂ ਜਮ੍ਹਾਂ ਕਰੋ।",
  "This marks all {count} payslip (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ਇਹ ਸਾਰੀਆਂ {count} ਤਨਖਾਹ ਪਰਚੀਆਂ (ਕੁੱਲ {amount}) ਨੂੰ ਭੁਗਤਾਨ ਹੋਈਆਂ ਵਜੋਂ ਦਰਜ ਕਰਦਾ ਹੈ ਅਤੇ ਇਹ ਪੇਰੋਲ ਰਨ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹੈ। ਇਹ ਆਪਣੇ ਆਪ ਪੈਸੇ ਟ੍ਰਾਂਸਫਰ ਨਹੀਂ ਕਰਦਾ — ਇਹ ਸਿਰਫ਼ ਦਰਜ ਕਰਦਾ ਹੈ ਕਿ ਟ੍ਰਾਂਸਫਰ ਪਹਿਲਾਂ ਹੀ ਹੋ ਚੁੱਕਾ ਹੈ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "This marks all {count} payslips (total {amount}) as paid and closes this payroll run. This does not itself transfer money — it records that the transfer already happened. This cannot be undone.": "ਇਹ ਸਾਰੀਆਂ {count} ਤਨਖਾਹ ਪਰਚੀਆਂ (ਕੁੱਲ {amount}) ਨੂੰ ਭੁਗਤਾਨ ਹੋਈਆਂ ਵਜੋਂ ਦਰਜ ਕਰਦਾ ਹੈ ਅਤੇ ਇਹ ਪੇਰੋਲ ਰਨ ਬੰਦ ਕਰ ਦਿੰਦਾ ਹੈ। ਇਹ ਆਪਣੇ ਆਪ ਪੈਸੇ ਟ੍ਰਾਂਸਫਰ ਨਹੀਂ ਕਰਦਾ — ਇਹ ਸਿਰਫ਼ ਦਰਜ ਕਰਦਾ ਹੈ ਕਿ ਟ੍ਰਾਂਸਫਰ ਪਹਿਲਾਂ ਹੀ ਹੋ ਚੁੱਕਾ ਹੈ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
