  "Statutory Deductions": "ਕਾਨੂੰਨੀ ਕਟੌਤੀਆਂ",
  "This recalculates salaries for all {count} employee in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ਇਹ ਇਸ ਚੱਕਰ ਦੇ ਸਾਰੇ {count} ਕਰਮਚਾਰੀ ਦੀ ਤਨਖਾਹ ਨੂੰ ਸ਼ੁਰੂ ਤੋਂ ਦੁਬਾਰਾ ਗਿਣਦਾ ਹੈ ਅਤੇ ਮੌਜੂਦਾ ਅੰਕੜਿਆਂ ਨੂੰ ਬਦਲ ਦਿੰਦਾ ਹੈ — ਇਨ੍ਹਾਂ ਤਨਖਾਹ ਪਰਚੀਆਂ ਤੇ ਪਹਿਲਾਂ ਕੀਤੇ ਕਿਸੇ ਵੀ ਹੱਥੀਂ ਬੋਨਸ ਜਾਂ ਖਰਚਾ ਵਾਪਸੀ ਦੇ ਸਮਾਯੋਜਨ ਸਮੇਤ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "This recalculates salaries for all {count} employees in this cycle from scratch, overwriting the current figures — including any manual bonus or reimbursement adjustments already made on these payslips. This cannot be undone.": "ਇਹ ਇਸ ਚੱਕਰ ਦੇ ਸਾਰੇ {count} ਕਰਮਚਾਰੀਆਂ ਦੀ ਤਨਖਾਹ ਨੂੰ ਸ਼ੁਰੂ ਤੋਂ ਦੁਬਾਰਾ ਗਿਣਦਾ ਹੈ ਅਤੇ ਮੌਜੂਦਾ ਅੰਕੜਿਆਂ ਨੂੰ ਬਦਲ ਦਿੰਦਾ ਹੈ — ਇਨ੍ਹਾਂ ਤਨਖਾਹ ਪਰਚੀਆਂ ਤੇ ਪਹਿਲਾਂ ਕੀਤੇ ਕਿਸੇ ਵੀ ਹੱਥੀਂ ਬੋਨਸ ਜਾਂ ਖਰਚਾ ਵਾਪਸੀ ਦੇ ਸਮਾਯੋਜਨ ਸਮੇਤ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "This will calculate salaries for all eligible employees using their CTC, salary structure, and statutory rules for each branch.": "ਇਹ ਹਰ ਬ੍ਰਾਂਚ ਲਈ ਸਾਰੇ ਯੋਗ ਕਰਮਚਾਰੀਆਂ ਦੀ ਤਨਖਾਹ ਦੀ ਗਣਨਾ ਉਨ੍ਹਾਂ ਦੇ CTC, ਤਨਖਾਹ ਢਾਂਚੇ ਅਤੇ ਕਾਨੂੰਨੀ ਨਿਯਮਾਂ ਅਨੁਸਾਰ ਕਰੇਗਾ।",
