  "Run Payroll — {branch}": "ਪੇਰੋਲ ਚਲਾਓ — {branch}",
  "Your account is not assigned to a branch. Payroll actions are unavailable until an administrator assigns you to a branch in Settings → Employees.": "ਤੁਹਾਡਾ ਖਾਤਾ ਕਿਸੇ ਬ੍ਰਾਂਚ ਨੂੰ ਨਹੀਂ ਸੌਂਪਿਆ ਗਿਆ। ਜਦੋਂ ਤੱਕ ਐਡਮਿਨ ਸੈਟਿੰਗਾਂ → ਕਰਮਚਾਰੀ ਵਿੱਚ ਤੁਹਾਨੂੰ ਕਿਸੇ ਬ੍ਰਾਂਚ ਨੂੰ ਨਹੀਂ ਸੌਂਪਦਾ, ਪੇਰੋਲ ਕਾਰਵਾਈਆਂ ਉਪਲਬਧ ਨਹੀਂ ਹਨ।",
