  "Dates are auto-filled from your Payroll Run Settings. Adjust month/year to change them.": "ਤਾਰੀਖਾਂ ਤੁਹਾਡੀਆਂ ਪੇਰੋਲ ਰਨ ਸੈਟਿੰਗਾਂ ਤੋਂ ਆਪਣੇ-ਆਪ ਭਰੀਆਂ ਗਈਆਂ ਹਨ। ਇਨ੍ਹਾਂ ਨੂੰ ਬਦਲਣ ਲਈ ਮਹੀਨਾ/ਸਾਲ ਬਦਲੋ।",
  "e.g. June 2026 regular payroll run": "ਉਦਾ. ਜੂਨ 2026 ਦਾ ਨਿਯਮਤ ਪੇਰੋਲ ਰਨ",
