  "Payroll settings not configured — dates default to month boundaries. Go to Settings → Payroll Configuration to set custom days.": "ਪੇਰੋਲ ਸੈਟਿੰਗਾਂ ਸੈੱਟ ਨਹੀਂ ਹਨ — ਤਾਰੀਖਾਂ ਮਹੀਨੇ ਦੀਆਂ ਹੱਦਾਂ ਤੇ ਰਹਿਣਗੀਆਂ। ਆਪਣੇ ਦਿਨ ਸੈੱਟ ਕਰਨ ਲਈ ਸੈਟਿੰਗਾਂ → ਪੇਰੋਲ ਸੰਰਚਨਾ ਤੇ ਜਾਓ।",
