  "ECR (Electronic Challan-cum-Return)": "ECR (ਇਲੈਕਟ੍ਰਾਨਿਕ ਚਲਾਨ-ਕਮ-ਰਿਟਰਨ)",
  "ECR export is available after a payroll cycle is completed and payslips are dispatched. Complete a payroll run first.": "ECR ਐਕਸਪੋਰਟ ਪੇਰੋਲ ਚੱਕਰ ਪੂਰਾ ਹੋਣ ਅਤੇ ਤਨਖਾਹ ਪਰਚੀਆਂ ਭੇਜੇ ਜਾਣ ਤੋਂ ਬਾਅਦ ਉਪਲਬਧ ਹੁੰਦਾ ਹੈ। ਪਹਿਲਾਂ ਇੱਕ ਪੇਰੋਲ ਰਨ ਪੂਰਾ ਕਰੋ।",
  "ECR is only available once payslips have been generated for this period.": "ECR ਸਿਰਫ਼ ਉਦੋਂ ਉਪਲਬਧ ਹੁੰਦਾ ਹੈ ਜਦੋਂ ਇਸ ਮਿਆਦ ਲਈ ਤਨਖਾਹ ਪਰਚੀਆਂ ਬਣ ਚੁੱਕੀਆਂ ਹੋਣ।",
  "Excel": "Excel",
  "Export ECR file for EPFO submission": "EPFO ਨੂੰ ਜਮ੍ਹਾਂ ਕਰਨ ਲਈ ECR ਫਾਈਲ ਐਕਸਪੋਰਟ ਕਰੋ",
