  "No payroll cycles yet. Run your first payroll to enable ECR export.": "ਹਾਲੇ ਤੱਕ ਕੋਈ ਪੇਰੋਲ ਚੱਕਰ ਨਹੀਂ। ECR ਐਕਸਪੋਰਟ ਚਾਲੂ ਕਰਨ ਲਈ ਆਪਣਾ ਪਹਿਲਾ ਪੇਰੋਲ ਚਲਾਓ।",
  "PDF": "PDF",
  "Select a period to export.": "ਐਕਸਪੋਰਟ ਕਰਨ ਲਈ ਇੱਕ ਮਿਆਦ ਚੁਣੋ।",
