  "{count} employees · Net:": "{count} ਕਰਮਚਾਰੀ · ਸ਼ੁੱਧ:",
  "All payslips dispatched. Employees have the configured window to raise queries.": "ਸਾਰੀਆਂ ਤਨਖਾਹ ਪਰਚੀਆਂ ਭੇਜ ਦਿੱਤੀਆਂ ਗਈਆਂ ਹਨ। ਕਰਮਚਾਰੀਆਂ ਕੋਲ ਸਵਾਲ ਉਠਾਉਣ ਲਈ ਤੈਅ ਕੀਤਾ ਸਮਾਂ ਹੈ।",
  "All payslips dispatched. Employees have until {date} to raise queries.": "ਸਾਰੀਆਂ ਤਨਖਾਹ ਪਰਚੀਆਂ ਭੇਜ ਦਿੱਤੀਆਂ ਗਈਆਂ ਹਨ। ਕਰਮਚਾਰੀਆਂ ਕੋਲ ਸਵਾਲ ਉਠਾਉਣ ਲਈ {date} ਤੱਕ ਦਾ ਸਮਾਂ ਹੈ।",
  "Continue to Mark as Paid": "ਭੁਗਤਾਨ ਹੋਇਆ ਦਰਜ ਕਰਨ ਲਈ ਜਾਰੀ ਰੱਖੋ",
  "Dispatch All": "ਸਭ ਭੇਜੋ",
