  "This will email payslips to all {count} employee in this cycle (total net pay {amount}). Employees will be able to view and query them immediately. This cannot be undone.": "ਇਹ ਇਸ ਚੱਕਰ ਦੇ ਸਾਰੇ {count} ਕਰਮਚਾਰੀ ਨੂੰ ਤਨਖਾਹ ਪਰਚੀਆਂ ਈਮੇਲ ਕਰੇਗਾ (ਕੁੱਲ ਸ਼ੁੱਧ ਤਨਖਾਹ {amount})। ਕਰਮਚਾਰੀ ਉਨ੍ਹਾਂ ਨੂੰ ਤੁਰੰਤ ਵੇਖ ਸਕਣਗੇ ਅਤੇ ਉਨ੍ਹਾਂ ਬਾਰੇ ਸਵਾਲ ਉਠਾ ਸਕਣਗੇ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "This will email payslips to all {count} employees in this cycle (total net pay {amount}). Employees will be able to view and query them immediately. This cannot be undone.": "ਇਹ ਇਸ ਚੱਕਰ ਦੇ ਸਾਰੇ {count} ਕਰਮਚਾਰੀਆਂ ਨੂੰ ਤਨਖਾਹ ਪਰਚੀਆਂ ਈਮੇਲ ਕਰੇਗਾ (ਕੁੱਲ ਸ਼ੁੱਧ ਤਨਖਾਹ {amount})। ਕਰਮਚਾਰੀ ਉਨ੍ਹਾਂ ਨੂੰ ਤੁਰੰਤ ਵੇਖ ਸਕਣਗੇ ਅਤੇ ਉਨ੍ਹਾਂ ਬਾਰੇ ਸਵਾਲ ਉਠਾ ਸਕਣਗੇ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
