  "{count} critical error(s)": "{count} ਗੰਭੀਰ ਗਲਤੀਆਂ",
  "{count} employee(s) earning above ₹21,000 have no deductions. Ensure statutory config is set for their branch.": "₹21,000 ਤੋਂ ਵੱਧ ਕਮਾਉਣ ਵਾਲੇ {count} ਕਰਮਚਾਰੀਆਂ ਦੀ ਕੋਈ ਕਟੌਤੀ ਨਹੀਂ ਹੈ। ਯਕੀਨੀ ਬਣਾਓ ਕਿ ਉਨ੍ਹਾਂ ਦੀ ਬ੍ਰਾਂਚ ਲਈ ਕਾਨੂੰਨੀ ਸੰਰਚਨਾ ਸੈੱਟ ਹੈ।",
  "{count} employee(s) have more than 15 LOP days. Verify this is correct before proceeding.": "{count} ਕਰਮਚਾਰੀਆਂ ਦੇ 15 ਤੋਂ ਵੱਧ LOP ਦਿਨ ਹਨ। ਅੱਗੇ ਵਧਣ ਤੋਂ ਪਹਿਲਾਂ ਜਾਂਚ ਕਰੋ ਕਿ ਇਹ ਸਹੀ ਹੈ।",
  "{count} employee(s) have negative net pay. Deductions exceed gross earnings — review LOP or advance recovery entries.": "{count} ਕਰਮਚਾਰੀਆਂ ਦੀ ਸ਼ੁੱਧ ਤਨਖਾਹ ਨਕਾਰਾਤਮਕ ਹੈ। ਕਟੌਤੀਆਂ ਕੁੱਲ ਕਮਾਈ ਤੋਂ ਵੱਧ ਹਨ — LOP ਜਾਂ ਪੇਸ਼ਗੀ ਵਸੂਲੀ ਦੀਆਂ ਐਂਟਰੀਆਂ ਦੀ ਸਮੀਖਿਆ ਕਰੋ।",
  "{count} employee(s) have zero gross earnings. Check that their CTC and salary structure are configured correctly.": "{count} ਕਰਮਚਾਰੀਆਂ ਦੀ ਕੁੱਲ ਕਮਾਈ ਜ਼ੀਰੋ ਹੈ। ਜਾਂਚੋ ਕਿ ਉਨ੍ਹਾਂ ਦਾ CTC ਅਤੇ ਤਨਖਾਹ ਢਾਂਚਾ ਸਹੀ ਸੈੱਟ ਹੈ।",
