  "Leave blank to file for yourself, or search an employee…": "ਆਪਣੇ ਲਈ ਦਰਜ ਕਰਨ ਲਈ ਖਾਲੀ ਛੱਡੋ, ਜਾਂ ਕਿਸੇ ਕਰਮਚਾਰੀ ਨੂੰ ਖੋਜੋ…",
