  "When someone resigns or an exit is raised, it shows up here with its approval progress.": "ਜਦੋਂ ਕੋਈ ਅਸਤੀਫ਼ਾ ਦਿੰਦਾ ਹੈ ਜਾਂ ਨਿਕਾਸ ਦੀ ਬੇਨਤੀ ਕੀਤੀ ਜਾਂਦੀ ਹੈ, ਤਾਂ ਇਹ ਇੱਥੇ ਮਨਜ਼ੂਰੀ ਦੀ ਪ੍ਰਗਤੀ ਸਮੇਤ ਦਿਖਾਈ ਦਿੰਦੀ ਹੈ।",
