  "{served} of {required} days served ({short} short). A recovery of {amount} has been calculated. Confirm with HR or finance whether this recovery applies before finalising.": "{required} ਵਿੱਚੋਂ {served} ਦਿਨ ਪੂਰੇ ਕੀਤੇ ({short} ਘੱਟ)। {amount} ਦੀ ਵਸੂਲੀ ਦੀ ਗਣਨਾ ਕੀਤੀ ਗਈ ਹੈ। ਅੰਤਿਮ ਰੂਪ ਦੇਣ ਤੋਂ ਪਹਿਲਾਂ HR ਜਾਂ ਵਿੱਤ ਵਿਭਾਗ ਤੋਂ ਪੁਸ਼ਟੀ ਕਰੋ ਕਿ ਇਹ ਵਸੂਲੀ ਲਾਗੂ ਹੁੰਦੀ ਹੈ ਜਾਂ ਨਹੀਂ।",
