  "Deductions exceed earnings — this amount is owed back by the employee, not paid to them.": "ਕਟੌਤੀਆਂ ਕਮਾਈ ਤੋਂ ਵੱਧ ਹਨ — ਇਹ ਰਕਮ ਕਰਮਚਾਰੀ ਨੂੰ ਵਾਪਸ ਕਰਨੀ ਪਵੇਗੀ, ਉਨ੍ਹਾਂ ਨੂੰ ਅਦਾ ਨਹੀਂ ਕੀਤੀ ਜਾਂਦੀ।",
  "Failed to finalize the settlement.": "ਸੈਟਲਮੈਂਟ ਨੂੰ ਅੰਤਿਮ ਰੂਪ ਨਹੀਂ ਦਿੱਤਾ ਜਾ ਸਕਿਆ।",
  "Failed to update the settlement.": "ਸੈਟਲਮੈਂਟ ਅੱਪਡੇਟ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Finalize": "ਅੰਤਿਮ ਰੂਪ ਦਿਓ",
  "Finalize this settlement?": "ਕੀ ਇਸ ਸੈਟਲਮੈਂਟ ਨੂੰ ਅੰਤਿਮ ਰੂਪ ਦੇਣਾ ਹੈ?",
  "Finalized by {name}": "{name} ਵੱਲੋਂ ਅੰਤਿਮ ਰੂਪ ਦਿੱਤਾ ਗਿਆ",
  "Finalizing…": "ਅੰਤਿਮ ਰੂਪ ਦਿੱਤਾ ਜਾ ਰਿਹਾ ਹੈ…",
  "Full {required}-day notice served": "ਪੂਰਾ {required}-ਦਿਨ ਦਾ ਨੋਟਿਸ ਪੂਰਾ ਕੀਤਾ",
  "Full & Final Settlement": "ਪੂਰਾ ਅਤੇ ਅੰਤਿਮ ਨਿਪਟਾਰਾ",
  "Leave Encashment": "ਛੁੱਟੀ ਦਾ ਨਕਦੀਕਰਨ",
  "Net Recoverable from Employee": "ਕਰਮਚਾਰੀ ਤੋਂ ਵਸੂਲਣਯੋਗ ਸ਼ੁੱਧ ਰਕਮ",
  "Notice Period Recovery": "ਨੋਟਿਸ ਮਿਆਦ ਦੀ ਵਸੂਲੀ",
  "Notice period shortfall:": "ਨੋਟਿਸ ਮਿਆਦ ਦੀ ਘਾਟ:",
  "Other Adjustment (+/−)": "ਹੋਰ ਸਮਾਯੋਜਨ (+/−)",
  "Other Adjustment Note": "ਹੋਰ ਸਮਾਯੋਜਨ ਨੋਟ",
  "Other Adjustment: {amount}": "ਹੋਰ ਸਮਾਯੋਜਨ: {amount}",
  "Pro-rata Salary": "ਅਨੁਪਾਤਕ ਤਨਖਾਹ",
  "Pro-rated salary, leave encashment, and notice-period shortfall are computed automatically (CTC ÷ 30, Earned Leave balance) — a starting estimate to review, not a final figure. Gratuity, bonus, reimbursements, advances, and TDS are always entered by hand.": "ਅਨੁਪਾਤਕ ਤਨਖਾਹ, ਛੁੱਟੀ ਦਾ ਨਕਦੀਕਰਨ ਅਤੇ ਨੋਟਿਸ ਮਿਆਦ ਦੀ ਘਾਟ ਆਪਣੇ-ਆਪ ਗਿਣੇ ਜਾਂਦੇ ਹਨ (CTC ÷ 30, ਕਮਾਈ ਹੋਈ ਛੁੱਟੀ ਦਾ ਬਕਾਇਆ) — ਇਹ ਸਮੀਖਿਆ ਲਈ ਸ਼ੁਰੂਆਤੀ ਅੰਦਾਜ਼ਾ ਹੈ, ਅੰਤਿਮ ਅੰਕੜਾ ਨਹੀਂ। ਗ੍ਰੈਚੂਟੀ, ਬੋਨਸ, ਖਰਚਾ ਵਾਪਸੀ, ਪੇਸ਼ਗੀਆਂ ਅਤੇ TDS ਹਮੇਸ਼ਾ ਹੱਥੀਂ ਦਾਖਲ ਕੀਤੇ ਜਾਂਦੇ ਹਨ।",
  "Settlement finalized.": "ਸੈਟਲਮੈਂਟ ਨੂੰ ਅੰਤਿਮ ਰੂਪ ਦਿੱਤਾ ਗਿਆ।",
  "Settlement updated.": "ਸੈਟਲਮੈਂਟ ਅੱਪਡੇਟ ਹੋ ਗਈ।",
  "This is a recovery — the employee owes the company (net payable may be negative)": "ਇਹ ਇੱਕ ਵਸੂਲੀ ਹੈ — ਕਰਮਚਾਰੀ ਕੰਪਨੀ ਦਾ ਦੇਣਦਾਰ ਹੈ (ਸ਼ੁੱਧ ਦੇਣਯੋਗ ਰਕਮ ਨਕਾਰਾਤਮਕ ਹੋ ਸਕਦੀ ਹੈ)",
  "This locks the full & final settlement at a net payable of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ਇਹ ਪੂਰੇ ਅਤੇ ਅੰਤਿਮ ਨਿਪਟਾਰੇ ਨੂੰ {amount} ਦੀ ਸ਼ੁੱਧ ਦੇਣਯੋਗ ਰਕਮ ਤੇ ਲੌਕ ਕਰ ਦਿੰਦਾ ਹੈ। ਅੰਤਿਮ ਰੂਪ ਦੇਣ ਤੋਂ ਬਾਅਦ ਇਸ ਸੈਟਲਮੈਂਟ ਦਾ ਕੋਈ ਵੀ ਖੇਤਰ — ਗ੍ਰੈਚੂਟੀ, ਬੋਨਸ, ਖਰਚਾ ਵਾਪਸੀ, ਪੇਸ਼ਗੀਆਂ, TDS ਜਾਂ ਸਮਾਯੋਜਨ — ਦੁਬਾਰਾ ਸੋਧਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "This locks the full & final settlement at a net recoverable from the employee of {amount}. Once finalized, no field on this settlement — gratuity, bonus, reimbursements, advances, TDS, or adjustments — can be edited again. This cannot be undone.": "ਇਹ ਪੂਰੇ ਅਤੇ ਅੰਤਿਮ ਨਿਪਟਾਰੇ ਨੂੰ ਕਰਮਚਾਰੀ ਤੋਂ {amount} ਦੀ ਸ਼ੁੱਧ ਵਸੂਲਣਯੋਗ ਰਕਮ ਤੇ ਲੌਕ ਕਰ ਦਿੰਦਾ ਹੈ। ਅੰਤਿਮ ਰੂਪ ਦੇਣ ਤੋਂ ਬਾਅਦ ਇਸ ਸੈਟਲਮੈਂਟ ਦਾ ਕੋਈ ਵੀ ਖੇਤਰ — ਗ੍ਰੈਚੂਟੀ, ਬੋਨਸ, ਖਰਚਾ ਵਾਪਸੀ, ਪੇਸ਼ਗੀਆਂ, TDS ਜਾਂ ਸਮਾਯੋਜਨ — ਦੁਬਾਰਾ ਸੋਧਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ। ਇਸਨੂੰ ਵਾਪਸ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ।",
  "What this adjustment is for": "ਇਹ ਸਮਾਯੋਜਨ ਕਿਸ ਲਈ ਹੈ",
