  "State-wise. One GSTIN per state. Each is checked against your PAN.": "ਰਾਜ ਅਨੁਸਾਰ। ਹਰ ਰਾਜ ਲਈ ਇੱਕ GSTIN। ਹਰ ਇੱਕ ਦੀ ਤੁਹਾਡੇ PAN ਨਾਲ ਜਾਂਚ ਕੀਤੀ ਜਾਂਦੀ ਹੈ।",
