  "Add only what applies. All optional.": "ਸਿਰਫ਼ ਉਹੀ ਜੋੜੋ ਜੋ ਲਾਗੂ ਹੁੰਦਾ ਹੈ। ਸਭ ਵਿਕਲਪਿਕ।",
