  "Entity type — this drives the rest of the form": "ਸੰਸਥਾ ਦੀ ਕਿਸਮ — ਬਾਕੀ ਫਾਰਮ ਇਸ ਤੇ ਨਿਰਭਰ ਕਰਦਾ ਹੈ",
  "Failed to save company info. Please try again.": "ਕੰਪਨੀ ਦੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹੋ ਸਕੀ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
