  "Save & validate": "ਸੁਰੱਖਿਅਤ ਕਰੋ ਅਤੇ ਪੜਤਾਲ ਕਰੋ",
  "Statutory and business details. The form adapts to your entity type, so you only see what applies to you.": "ਕਾਨੂੰਨੀ ਅਤੇ ਕਾਰੋਬਾਰੀ ਵੇਰਵੇ। ਫਾਰਮ ਤੁਹਾਡੀ ਸੰਸਥਾ ਕਿਸਮ ਅਨੁਸਾਰ ਬਦਲਦਾ ਹੈ, ਇਸ ਲਈ ਤੁਹਾਨੂੰ ਸਿਰਫ਼ ਉਹੀ ਦਿਸਦਾ ਹੈ ਜੋ ਤੁਹਾਡੇ ਤੇ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।",
  "as a placeholder — shown to teammates sharing the same reporting manager.": "ਪਲੇਸਹੋਲਡਰ ਵਜੋਂ — ਇੱਕੋ ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰ ਵਾਲੇ ਸਾਥੀਆਂ ਨੂੰ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।",
  "as a placeholder — shown to the employee's reporting manager.": "ਪਲੇਸਹੋਲਡਰ ਵਜੋਂ — ਕਰਮਚਾਰੀ ਦੇ ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰ ਨੂੰ ਦਿਖਾਇਆ ਜਾਂਦਾ ਹੈ।",
  "Automatic Birthday Wishes": "ਆਟੋਮੈਟਿਕ ਜਨਮ ਦਿਨ ਦੀਆਂ ਸ਼ੁਭਕਾਮਨਾਵਾਂ",
  "Birthday wishes settings updated": "ਜਨਮ ਦਿਨ ਸ਼ੁਭਕਾਮਨਾਵਾਂ ਦੀਆਂ ਸੈਟਿੰਗਾਂ ਅੱਪਡੇਟ ਹੋ ਗਈਆਂ",
  "Dashboard banner and notification copy shown to the employee, their team, and their manager on someone's birthday.": "ਕਿਸੇ ਦੇ ਜਨਮ ਦਿਨ ਤੇ ਕਰਮਚਾਰੀ, ਉਸਦੀ ਟੀਮ ਅਤੇ ਉਸਦੇ ਮੈਨੇਜਰ ਨੂੰ ਦਿਖਾਇਆ ਜਾਣ ਵਾਲਾ ਡੈਸ਼ਬੋਰਡ ਬੈਨਰ ਅਤੇ ਸੂਚਨਾ ਦਾ ਲਿਖਤ।",
