  "Every ID is 8 digits and purely numeric. Each worker type has its own range, so the first digit tells you the type. The ID is picked automatically at hire; changing someone's type later does not change their existing ID.": "ਹਰ ID 8 ਅੰਕਾਂ ਦੀ ਅਤੇ ਸਿਰਫ਼ ਸੰਖਿਆਤਮਕ ਹੁੰਦੀ ਹੈ। ਹਰ ਕਿਸਮ ਦੇ ਕਰਮਚਾਰੀ ਦੀ ਆਪਣੀ ਰੇਂਜ ਹੈ, ਇਸ ਲਈ ਪਹਿਲਾ ਅੰਕ ਕਿਸਮ ਦੱਸਦਾ ਹੈ। ID ਭਰਤੀ ਵੇਲੇ ਆਪਣੇ-ਆਪ ਚੁਣੀ ਜਾਂਦੀ ਹੈ; ਬਾਅਦ ਵਿੱਚ ਕਿਸੇ ਦੀ ਕਿਸਮ ਬਦਲਣ ਨਾਲ ਉਸਦੀ ਮੌਜੂਦਾ ID ਨਹੀਂ ਬਦਲਦੀ।",
