  "Defaults to the next payroll cycle; issued payslips are not recalculated.": "ਡਿਫਾਲਟ ਅਗਲਾ ਪੇਰੋਲ ਚੱਕਰ ਹੈ; ਜਾਰੀ ਹੋ ਚੁੱਕੀਆਂ ਤਨਖਾਹ ਪਰਚੀਆਂ ਦੁਬਾਰਾ ਨਹੀਂ ਗਿਣੀਆਂ ਜਾਂਦੀਆਂ।",
