  "Enabling {name} affects {count} employee(s). Previously stored overrides will not be reused; a fresh value must be entered where required.": "{name} ਚਾਲੂ ਕਰਨ ਨਾਲ {count} ਕਰਮਚਾਰੀ ਪ੍ਰਭਾਵਿਤ ਹੋਣਗੇ। ਪਹਿਲਾਂ ਸੁਰੱਖਿਅਤ ਕੀਤੇ ਓਵਰਰਾਈਡ ਦੁਬਾਰਾ ਨਹੀਂ ਵਰਤੇ ਜਾਣਗੇ; ਜਿੱਥੇ ਲੋੜ ਹੋਵੇ ਉੱਥੇ ਨਵਾਂ ਮੁੱਲ ਦਾਖਲ ਕਰਨਾ ਪਵੇਗਾ।",
