  "Use this structure as the default when setting up employee compensation.": "ਕਰਮਚਾਰੀ ਮਿਹਨਤਾਨਾ ਸੈੱਟ ਕਰਦੇ ਸਮੇਂ ਇਸ ਢਾਂਚੇ ਨੂੰ ਡਿਫਾਲਟ ਵਜੋਂ ਵਰਤੋ।",
