  "You can punch from any location on these days.": "ਇਨ੍ਹਾਂ ਦਿਨਾਂ ਤੇ ਤੁਸੀਂ ਕਿਸੇ ਵੀ ਥਾਂ ਤੋਂ ਪੰਚ ਕਰ ਸਕਦੇ ਹੋ।",
  "You must punch near this location. If you have moved, ask your manager or HR to allow punching from any location.": "ਤੁਹਾਨੂੰ ਇਸ ਥਾਂ ਦੇ ਨੇੜੇ ਪੰਚ ਕਰਨਾ ਪਵੇਗਾ। ਜੇ ਤੁਸੀਂ ਕਿਤੇ ਹੋਰ ਚਲੇ ਗਏ ਹੋ ਤਾਂ ਆਪਣੇ ਮੈਨੇਜਰ ਜਾਂ HR ਨੂੰ ਕਿਸੇ ਵੀ ਥਾਂ ਤੋਂ ਪੰਚ ਕਰਨ ਦੀ ਇਜਾਜ਼ਤ ਦੇਣ ਲਈ ਕਹੋ।",
