  "A nominee is picked from the family list, and there is nobody in it yet. Add a family member with a name above, then add the nominee.": "ਨਾਮਜ਼ਦ ਵਿਅਕਤੀ ਪਰਿਵਾਰ ਦੀ ਸੂਚੀ ਵਿੱਚੋਂ ਚੁਣਿਆ ਜਾਂਦਾ ਹੈ, ਅਤੇ ਇਸ ਵਿੱਚ ਹਾਲੇ ਕੋਈ ਨਹੀਂ ਹੈ। ਉੱਪਰ ਨਾਮ ਸਮੇਤ ਇੱਕ ਪਰਿਵਾਰਕ ਮੈਂਬਰ ਜੋੜੋ, ਫਿਰ ਨਾਮਜ਼ਦ ਵਿਅਕਤੀ ਜੋੜੋ।",
  "Add a family member with a name above before adding a nominee.": "ਨਾਮਜ਼ਦ ਵਿਅਕਤੀ ਜੋੜਨ ਤੋਂ ਪਹਿਲਾਂ ਉੱਪਰ ਨਾਮ ਸਮੇਤ ਇੱਕ ਪਰਿਵਾਰਕ ਮੈਂਬਰ ਜੋੜੋ।",
  "Add the people who depend on the employee or who may be nominated below. A person is added once and can be picked as a nominee.": "ਹੇਠਾਂ ਉਨ੍ਹਾਂ ਲੋਕਾਂ ਨੂੰ ਜੋੜੋ ਜੋ ਕਰਮਚਾਰੀ ਤੇ ਨਿਰਭਰ ਹਨ ਜਾਂ ਜਿਨ੍ਹਾਂ ਨੂੰ ਨਾਮਜ਼ਦ ਕੀਤਾ ਜਾ ਸਕਦਾ ਹੈ। ਇੱਕ ਵਿਅਕਤੀ ਇੱਕ ਵਾਰ ਜੋੜਿਆ ਜਾਂਦਾ ਹੈ ਅਤੇ ਨਾਮਜ਼ਦ ਵਿਅਕਤੀ ਵਜੋਂ ਚੁਣਿਆ ਜਾ ਸਕਦਾ ਹੈ।",
  "Another {relationship} is already listed.": "ਇੱਕ ਹੋਰ {relationship} ਪਹਿਲਾਂ ਹੀ ਸੂਚੀ ਵਿੱਚ ਹੈ।",
  "Each scheme's shares should add up to 100% across its nominees. Pick nominees from the family list above.": "ਹਰ ਯੋਜਨਾ ਦੇ ਹਿੱਸੇ ਉਸਦੇ ਨਾਮਜ਼ਦ ਵਿਅਕਤੀਆਂ ਵਿੱਚ ਕੁੱਲ 100% ਬਣਨੇ ਚਾਹੀਦੇ ਹਨ। ਉੱਪਰ ਦਿੱਤੀ ਪਰਿਵਾਰ ਸੂਚੀ ਵਿੱਚੋਂ ਨਾਮਜ਼ਦ ਵਿਅਕਤੀ ਚੁਣੋ।",
  "EPF / Gratuity nomination": "EPF / ਗ੍ਰੈਚੂਟੀ ਨਾਮਜ਼ਦਗੀ",
  "No family members yet. This is optional; use the buttons above to add someone.": "ਹਾਲੇ ਤੱਕ ਕੋਈ ਪਰਿਵਾਰਕ ਮੈਂਬਰ ਨਹੀਂ। ਇਹ ਵਿਕਲਪਿਕ ਹੈ; ਕਿਸੇ ਨੂੰ ਜੋੜਨ ਲਈ ਉੱਪਰ ਦਿੱਤੇ ਬਟਨ ਵਰਤੋ।",
