  "on any section to go back and change it — nothing is sent to HR until you press": "ਕਿਸੇ ਵੀ ਭਾਗ ਤੇ ਵਾਪਸ ਜਾ ਕੇ ਬਦਲਣ ਲਈ — ਜਦੋਂ ਤੱਕ ਤੁਸੀਂ ਇਹ ਨਹੀਂ ਦਬਾਉਂਦੇ, HR ਨੂੰ ਕੁਝ ਨਹੀਂ ਭੇਜਿਆ ਜਾਂਦਾ",
