  "Drag and drop a file onto any row below, or click Upload. Accepted: PDF, JPG, PNG · Max 5 MB each.": "ਹੇਠਾਂ ਕਿਸੇ ਵੀ ਕਤਾਰ ਉੱਤੇ ਫਾਈਲ ਖਿੱਚ ਕੇ ਛੱਡੋ, ਜਾਂ ਅੱਪਲੋਡ ਤੇ ਕਲਿੱਕ ਕਰੋ। ਮਨਜ਼ੂਰ: PDF, JPG, PNG · ਹਰੇਕ ਵੱਧ ਤੋਂ ਵੱਧ 5 MB।",
