  "You won't be able to submit your onboarding profile until this step is complete.": "ਜਦੋਂ ਤੱਕ ਇਹ ਪੜਾਅ ਪੂਰਾ ਨਹੀਂ ਹੁੰਦਾ, ਤੁਸੀਂ ਆਪਣੀ ਆਨਬੋਰਡਿੰਗ ਪ੍ਰੋਫਾਈਲ ਜਮ੍ਹਾਂ ਨਹੀਂ ਕਰ ਸਕੋਗੇ।",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, and it takes effect immediately.": "ਤੁਹਾਡੇ ਸੰਗਠਨ ਨੂੰ ਵੈੱਬ ਕਲੌਕ-ਇਨ/ਆਊਟ ਲਈ ਰਜਿਸਟਰ ਕੀਤੀ Face ID ਚਾਹੀਦੀ ਹੈ। ਇੱਥੇ ਇੱਕ ਵਾਰ ਰਜਿਸਟਰ ਕਰੋ — ਅਸੀਂ ਇਹ ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਇੱਕ ਤੇਜ਼ ਜੀਵਿਤਤਾ ਜਾਂਚ ਕਰਦੇ ਹਾਂ ਕਿ ਇਹ ਸੱਚਮੁੱਚ ਤੁਸੀਂ ਹੀ ਹੋ, ਅਤੇ ਇਹ ਤੁਰੰਤ ਲਾਗੂ ਹੋ ਜਾਂਦੀ ਹੈ।",
  "Your organisation requires a registered face ID for web clock-in/out. Register once here — we run a quick liveness check to confirm it's really you, then send it to HR for approval.": "ਤੁਹਾਡੇ ਸੰਗਠਨ ਨੂੰ ਵੈੱਬ ਕਲੌਕ-ਇਨ/ਆਊਟ ਲਈ ਰਜਿਸਟਰ ਕੀਤੀ Face ID ਚਾਹੀਦੀ ਹੈ। ਇੱਥੇ ਇੱਕ ਵਾਰ ਰਜਿਸਟਰ ਕਰੋ — ਅਸੀਂ ਇਹ ਪੁਸ਼ਟੀ ਕਰਨ ਲਈ ਇੱਕ ਤੇਜ਼ ਜੀਵਿਤਤਾ ਜਾਂਚ ਕਰਦੇ ਹਾਂ ਕਿ ਇਹ ਸੱਚਮੁੱਚ ਤੁਸੀਂ ਹੀ ਹੋ, ਫਿਰ ਮਨਜ਼ੂਰੀ ਲਈ HR ਨੂੰ ਭੇਜ ਦਿੰਦੇ ਹਾਂ।",
