  "Your HR team will assign assessments before you can proceed to the dashboard.": "ਡੈਸ਼ਬੋਰਡ ਤੇ ਜਾਣ ਤੋਂ ਪਹਿਲਾਂ ਤੁਹਾਡੀ HR ਟੀਮ ਤੁਹਾਨੂੰ ਮੁਲਾਂਕਣ ਸੌਂਪੇਗੀ।",
  "Your progress has been saved.": "ਤੁਹਾਡੀ ਪ੍ਰਗਤੀ ਸੁਰੱਖਿਅਤ ਕਰ ਲਈ ਗਈ ਹੈ।",
  "A bank detail change you submitted is awaiting HR review — your previous details remain active for payroll until it's approved.": "ਤੁਹਾਡੇ ਵੱਲੋਂ ਜਮ੍ਹਾਂ ਕੀਤੀ ਬੈਂਕ ਵੇਰਵਿਆਂ ਦੀ ਤਬਦੀਲੀ HR ਦੀ ਸਮੀਖਿਆ ਦੀ ਉਡੀਕ ਵਿੱਚ ਹੈ — ਮਨਜ਼ੂਰ ਹੋਣ ਤੱਕ ਪੇਰੋਲ ਲਈ ਤੁਹਾਡੇ ਪਿਛਲੇ ਵੇਰਵੇ ਹੀ ਲਾਗੂ ਰਹਿਣਗੇ।",
  "Approved — check your email": "ਮਨਜ਼ੂਰ ਹੋ ਗਿਆ — ਆਪਣੀ ਈਮੇਲ ਵੇਖੋ",
