  "Complete Face ID registration (Step 6) to enable submission.": "ਜਮ੍ਹਾਂ ਕਰਨ ਦੀ ਸਹੂਲਤ ਚਾਲੂ ਕਰਨ ਲਈ Face ID ਰਜਿਸਟ੍ਰੇਸ਼ਨ (ਕਦਮ 6) ਪੂਰੀ ਕਰੋ।",
  "Complete your profile": "ਆਪਣੀ ਪ੍ਰੋਫਾਈਲ ਪੂਰੀ ਕਰੋ",
  "Could not remove this document. Please try again.": "ਇਹ ਦਸਤਾਵੇਜ਼ ਹਟਾਇਆ ਨਹੀਂ ਜਾ ਸਕਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Enter your PAN number before uploading the PAN card.": "PAN ਕਾਰਡ ਅੱਪਲੋਡ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ ਆਪਣਾ PAN ਨੰਬਰ ਦਾਖਲ ਕਰੋ।",
  "Fill in your details to get started. Your information is kept secure.": "ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਆਪਣੇ ਵੇਰਵੇ ਭਰੋ। ਤੁਹਾਡੀ ਜਾਣਕਾਰੀ ਸੁਰੱਖਿਅਤ ਰੱਖੀ ਜਾਂਦੀ ਹੈ।",
  "HR has approved your onboarding.": "HR ਨੇ ਤੁਹਾਡੀ ਆਨਬੋਰਡਿੰਗ ਮਨਜ਼ੂਰ ਕਰ ਦਿੱਤੀ ਹੈ।",
  "HR sent this back for corrections:": "HR ਨੇ ਇਹ ਸੁਧਾਈ ਲਈ ਵਾਪਸ ਭੇਜਿਆ ਹੈ:",
  "Name is required for every family member — remove any blank ones, or fill them in.": "ਹਰ ਪਰਿਵਾਰਕ ਮੈਂਬਰ ਦਾ ਨਾਮ ਲੋੜੀਂਦਾ ਹੈ — ਖਾਲੀ ਵਾਲੇ ਹਟਾਓ ਜਾਂ ਭਰ ਦਿਓ।",
  "Not saved yet. Check your connection; Save & Continue will retry": "ਹਾਲੇ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹੋਇਆ। ਆਪਣਾ ਕੁਨੈਕਸ਼ਨ ਜਾਂਚੋ; “ਸੁਰੱਖਿਅਤ ਕਰੋ ਅਤੇ ਜਾਰੀ ਰੱਖੋ” ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੇਗਾ",
  "Please fill in: {fields}": "ਕਿਰਪਾ ਕਰਕੇ ਭਰੋ: {fields}",
  "Please review and resubmit — contact HR for details.": "ਕਿਰਪਾ ਕਰਕੇ ਸਮੀਖਿਆ ਕਰਕੇ ਦੁਬਾਰਾ ਜਮ੍ਹਾਂ ਕਰੋ — ਵੇਰਵਿਆਂ ਲਈ HR ਨਾਲ ਸੰਪਰਕ ਕਰੋ।",
  "Profile Submitted!": "ਪ੍ਰੋਫਾਈਲ ਜਮ੍ਹਾਂ ਹੋ ਗਈ!",
  "Save Draft": "ਡਰਾਫਟ ਸੁਰੱਖਿਅਤ ਕਰੋ",
  "Saved successfully.": "ਸਫਲਤਾਪੂਰਵਕ ਸੁਰੱਖਿਅਤ ਹੋ ਗਿਆ।",
  "Select a family member for every nominee — remove any incomplete ones, or fill them in.": "ਹਰ ਨਾਮਜ਼ਦ ਲਈ ਇੱਕ ਪਰਿਵਾਰਕ ਮੈਂਬਰ ਚੁਣੋ — ਅਧੂਰੇ ਵਾਲੇ ਹਟਾਓ ਜਾਂ ਭਰ ਦਿਓ।",
  "Select an asset type for every entry — remove any incomplete ones, or fill them in.": "ਹਰ ਐਂਟਰੀ ਲਈ ਸੰਪਤੀ ਦੀ ਕਿਸਮ ਚੁਣੋ — ਅਧੂਰੀਆਂ ਹਟਾਓ ਜਾਂ ਭਰ ਦਿਓ।",
  "Still awaiting HR review — check back later, or wait for the email notification.": "ਹਾਲੇ HR ਦੀ ਸਮੀਖਿਆ ਬਾਕੀ ਹੈ — ਬਾਅਦ ਵਿੱਚ ਦੁਬਾਰਾ ਵੇਖੋ, ਜਾਂ ਈਮੇਲ ਸੂਚਨਾ ਦੀ ਉਡੀਕ ਕਰੋ।",
  "We have emailed you a link to set your password and activate your account.": "ਅਸੀਂ ਤੁਹਾਨੂੰ ਪਾਸਵਰਡ ਸੈੱਟ ਕਰਨ ਅਤੇ ਖਾਤਾ ਚਾਲੂ ਕਰਨ ਲਈ ਇੱਕ ਲਿੰਕ ਈਮੇਲ ਕੀਤਾ ਹੈ।",
  "You can close this tab and continue from the email.": "ਤੁਸੀਂ ਇਹ ਟੈਬ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ ਅਤੇ ਈਮੇਲ ਤੋਂ ਜਾਰੀ ਰੱਖ ਸਕਦੇ ਹੋ।",
  "You can close this tab. We will notify you by email when approved.": "ਤੁਸੀਂ ਇਹ ਟੈਬ ਬੰਦ ਕਰ ਸਕਦੇ ਹੋ। ਮਨਜ਼ੂਰ ਹੋਣ ਤੇ ਅਸੀਂ ਤੁਹਾਨੂੰ ਈਮੇਲ ਰਾਹੀਂ ਸੂਚਿਤ ਕਰਾਂਗੇ।",
  "You will receive access once approved.": "ਮਨਜ਼ੂਰੀ ਮਿਲਣ ਤੇ ਤੁਹਾਨੂੰ ਪਹੁੰਚ ਮਿਲ ਜਾਵੇਗੀ।",
  "Your onboarding details have been sent for HR review.": "ਤੁਹਾਡੇ ਆਨਬੋਰਡਿੰਗ ਵੇਰਵੇ HR ਦੀ ਸਮੀਖਿਆ ਲਈ ਭੇਜ ਦਿੱਤੇ ਗਏ ਹਨ।",
  "Opening your onboarding…": "ਤੁਹਾਡੀ ਆਨਬੋਰਡਿੰਗ ਖੁੱਲ੍ਹ ਰਹੀ ਹੈ…",
  "This link can't be used": "ਇਹ ਲਿੰਕ ਵਰਤਿਆ ਨਹੀਂ ਜਾ ਸਕਦਾ",
  "Ask HR to reset your password again, or": "HR ਨੂੰ ਆਪਣਾ ਪਾਸਵਰਡ ਦੁਬਾਰਾ ਰੀਸੈੱਟ ਕਰਨ ਲਈ ਕਹੋ, ਜਾਂ",
  "Checking your reset link…": "ਤੁਹਾਡਾ ਰੀਸੈੱਟ ਲਿੰਕ ਜਾਂਚਿਆ ਜਾ ਰਿਹਾ ਹੈ…",
  "Log in with your new password to continue.": "ਜਾਰੀ ਰੱਖਣ ਲਈ ਆਪਣੇ ਨਵੇਂ ਪਾਸਵਰਡ ਨਾਲ ਲੌਗਇਨ ਕਰੋ।",
  "Password set": "ਪਾਸਵਰਡ ਸੈੱਟ ਹੋ ਗਿਆ",
  "Set new password": "ਨਵਾਂ ਪਾਸਵਰਡ ਸੈੱਟ ਕਰੋ",
  "Setting password…": "ਪਾਸਵਰਡ ਸੈੱਟ ਹੋ ਰਿਹਾ ਹੈ…",
  "This reset link is invalid or has expired.": "ਇਹ ਰੀਸੈੱਟ ਲਿੰਕ ਅਵੈਧ ਹੈ ਜਾਂ ਇਸਦੀ ਮਿਆਦ ਖਤਮ ਹੋ ਗਈ ਹੈ।",
  "Your password was reset by HR. Set a new one to continue signing in as": "ਤੁਹਾਡਾ ਪਾਸਵਰਡ HR ਦੁਆਰਾ ਰੀਸੈੱਟ ਕੀਤਾ ਗਿਆ ਹੈ। ਇਸ ਵਜੋਂ ਸਾਈਨ ਇਨ ਜਾਰੀ ਰੱਖਣ ਲਈ ਨਵਾਂ ਪਾਸਵਰਡ ਸੈੱਟ ਕਰੋ:",
  "Choose someone only if L1 should differ from what the approval rule gives.": "ਕਿਸੇ ਨੂੰ ਤਾਂ ਹੀ ਚੁਣੋ ਜੇ L1 ਮਨਜ਼ੂਰੀ ਨਿਯਮ ਤੋਂ ਮਿਲਣ ਵਾਲੇ ਨਾਲੋਂ ਵੱਖਰਾ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "Could not load the list of people. Try again in a moment.": "ਲੋਕਾਂ ਦੀ ਸੂਚੀ ਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ। ਥੋੜ੍ਹੀ ਦੇਰ ਬਾਅਦ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Follow the org chart": "ਸੰਗਠਨ ਚਾਰਟ ਅਨੁਸਾਰ ਚੱਲੋ",
  "L1 approver (leave)": "L1 ਮਨਜ਼ੂਰੀ ਦੇਣ ਵਾਲਾ (ਛੁੱਟੀ)",
  "Leave empty to use the head of the employee's org unit.": "ਕਰਮਚਾਰੀ ਦੀ ਸੰਗਠਨ ਇਕਾਈ ਦੇ ਮੁਖੀ ਨੂੰ ਵਰਤਣ ਲਈ ਖਾਲੀ ਛੱਡੋ।",
  "The HR partner who gives the second approval.": "HR ਪਾਰਟਨਰ ਜੋ ਦੂਜੀ ਮਨਜ਼ੂਰੀ ਦਿੰਦਾ ਹੈ।",
  "Checking who will approve this request…": "ਇਹ ਜਾਂਚਿਆ ਜਾ ਰਿਹਾ ਹੈ ਕਿ ਇਹ ਬੇਨਤੀ ਕੌਣ ਮਨਜ਼ੂਰ ਕਰੇਗਾ…",
  "I understand and want to submit anyway": "ਮੈਂ ਸਮਝਦਾ/ਸਮਝਦੀ ਹਾਂ ਅਤੇ ਫਿਰ ਵੀ ਜਮ੍ਹਾਂ ਕਰਨਾ ਚਾਹੁੰਦਾ/ਚਾਹੁੰਦੀ ਹਾਂ",
