  "{person} (no longer eligible)": "{person} (ਹੁਣ ਯੋਗ ਨਹੀਂ)",
  "Could not load your approvers right now.": "ਇਸ ਵੇਲੇ ਤੁਹਾਡੇ ਮਨਜ਼ੂਰੀ ਦੇਣ ਵਾਲੇ ਲੋਡ ਨਹੀਂ ਹੋ ਸਕੇ।",
  "Not needed: managers' leave goes straight to HR": "ਲੋੜ ਨਹੀਂ: ਮੈਨੇਜਰਾਂ ਦੀ ਛੁੱਟੀ ਸਿੱਧੀ HR ਕੋਲ ਜਾਂਦੀ ਹੈ",
  "These people approve your leave requests. Ask HR if something here is wrong or missing.": "ਇਹ ਲੋਕ ਤੁਹਾਡੀਆਂ ਛੁੱਟੀ ਬੇਨਤੀਆਂ ਮਨਜ਼ੂਰ ਕਰਦੇ ਹਨ। ਜੇ ਇੱਥੇ ਕੁਝ ਗਲਤ ਜਾਂ ਗੁੰਮ ਹੈ ਤਾਂ HR ਨੂੰ ਪੁੱਛੋ।",
  "YOUR REPORTING & APPROVALS": "ਤੁਹਾਡੀ ਰਿਪੋਰਟਿੰਗ ਅਤੇ ਮਨਜ਼ੂਰੀਆਂ",
