  "Choose a strong password for your account.": "ਆਪਣੇ ਖਾਤੇ ਲਈ ਮਜ਼ਬੂਤ ਪਾਸਵਰਡ ਚੁਣੋ।",
  "Enter OTP": "OTP ਦਾਖਲ ਕਰੋ",
  "Enter your new password.": "ਆਪਣਾ ਨਵਾਂ ਪਾਸਵਰਡ ਦਾਖਲ ਕਰੋ।",
  "Enter your registered email and we'll send you a one-time code.": "ਆਪਣੀ ਰਜਿਸਟਰਡ ਈਮੇਲ ਦਾਖਲ ਕਰੋ ਅਤੇ ਅਸੀਂ ਤੁਹਾਨੂੰ ਇੱਕ ਵਾਰ ਵਰਤਣ ਵਾਲਾ ਕੋਡ ਭੇਜਾਂਗੇ।",
  "Invalid or expired OTP.": "OTP ਅਵੈਧ ਹੈ ਜਾਂ ਉਸਦੀ ਮਿਆਦ ਖਤਮ ਹੋ ਗਈ ਹੈ।",
