  "Password reset failed. Please try again.": "ਪਾਸਵਰਡ ਰੀਸੈੱਟ ਅਸਫਲ ਰਿਹਾ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
