  "…and {count} more.": "…ਅਤੇ {count} ਹੋਰ।",
  "“Sent” means the mail server accepted the email. It does not prove the employee's inbox received it.": "“ਭੇਜੀ ਗਈ” ਦਾ ਮਤਲਬ ਹੈ ਕਿ ਮੇਲ ਸਰਵਰ ਨੇ ਈਮੇਲ ਸਵੀਕਾਰ ਕੀਤੀ। ਇਸਦਾ ਇਹ ਸਬੂਤ ਨਹੀਂ ਕਿ ਕਰਮਚਾਰੀ ਦੇ ਇਨਬਾਕਸ ਵਿੱਚ ਪਹੁੰਚ ਗਈ।",
