  "Cancel import": "ਇੰਪੋਰਟ ਰੱਦ ਕਰੋ",
  "Cancelling stops after the current batch. Employees already created stay.": "ਰੱਦ ਕਰਨ ਤੇ ਮੌਜੂਦਾ ਬੈਚ ਤੋਂ ਬਾਅਦ ਰੁਕ ਜਾਵੇਗਾ। ਜੋ ਕਰਮਚਾਰੀ ਪਹਿਲਾਂ ਬਣ ਚੁੱਕੇ ਹਨ ਉਹ ਰਹਿਣਗੇ।",
