  "Import progress": "ਇੰਪੋਰਟ ਦੀ ਪ੍ਰਗਤੀ",
  "Retry {count} failed email": "{count} ਅਸਫਲ ਈਮੇਲ ਦੁਬਾਰਾ ਭੇਜੋ",
  "Retry {count} failed emails": "{count} ਅਸਫਲ ਈਮੇਲਾਂ ਦੁਬਾਰਾ ਭੇਜੋ",
