  "Basic pay saved — ₹{amount} per annum, effective {date}.": "ਮੁੱਢਲੀ ਤਨਖਾਹ ਸੁਰੱਖਿਅਤ ਹੋਈ — ₹{amount} ਸਾਲਾਨਾ, {date} ਤੋਂ ਲਾਗੂ।",
  "Could not save this pay record.": "ਇਹ ਤਨਖਾਹ ਰਿਕਾਰਡ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹੋ ਸਕਿਆ।",
  "Enter an annual CTC greater than zero.": "ਸਿਫ਼ਰ ਤੋਂ ਵੱਧ ਸਾਲਾਨਾ CTC ਦਾਖਲ ਕਰੋ।",
  "Must be on or after {date}.": "{date} ਨੂੰ ਜਾਂ ਉਸ ਤੋਂ ਬਾਅਦ ਹੋਣਾ ਚਾਹੀਦਾ ਹੈ।",
  "Updating the record in force from {date}.": "{date} ਤੋਂ ਲਾਗੂ ਰਿਕਾਰਡ ਅੱਪਡੇਟ ਕੀਤਾ ਜਾ ਰਿਹਾ ਹੈ।",
  "Location access is required for office punch in/out. Please allow location in your browser settings.": "ਦਫ਼ਤਰ ਦੇ ਪੰਚ ਇਨ/ਆਊਟ ਲਈ ਲੋਕੇਸ਼ਨ ਦੀ ਪਹੁੰਚ ਲੋੜੀਂਦੀ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੀਆਂ ਬ੍ਰਾਊਜ਼ਰ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਲੋਕੇਸ਼ਨ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ।",
  "Location access is required for work-from-home punch in/out. Please allow location in your browser settings.": "ਘਰ ਤੋਂ ਕੰਮ ਦੇ ਪੰਚ ਇਨ/ਆਊਟ ਲਈ ਲੋਕੇਸ਼ਨ ਦੀ ਪਹੁੰਚ ਲੋੜੀਂਦੀ ਹੈ। ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੀਆਂ ਬ੍ਰਾਊਜ਼ਰ ਸੈਟਿੰਗਾਂ ਵਿੱਚ ਲੋਕੇਸ਼ਨ ਦੀ ਇਜਾਜ਼ਤ ਦਿਓ।",
  "Please register your Face ID first (Profile > Register My Face), then come back to punch in.": "ਕਿਰਪਾ ਕਰਕੇ ਪਹਿਲਾਂ ਆਪਣੀ Face ID ਰਜਿਸਟਰ ਕਰੋ (ਪ੍ਰੋਫਾਈਲ > ਮੇਰਾ ਚਿਹਰਾ ਰਜਿਸਟਰ ਕਰੋ), ਫਿਰ ਪੰਚ ਇਨ ਕਰਨ ਲਈ ਵਾਪਸ ਆਓ।",
  "Punch failed. Please try again.": "ਪੰਚ ਅਸਫਲ ਰਿਹਾ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Punched in successfully.": "ਪੰਚ ਇਨ ਸਫਲ ਰਿਹਾ।",
  "Punched out successfully.": "ਪੰਚ ਆਊਟ ਸਫਲ ਰਿਹਾ।",
  "Too many failed face verification attempts. Please wait {time} before trying again.": "ਚਿਹਰੇ ਦੀ ਤਸਦੀਕ ਦੀਆਂ ਬਹੁਤ ਸਾਰੀਆਂ ਅਸਫਲ ਕੋਸ਼ਿਸ਼ਾਂ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰਨ ਤੋਂ ਪਹਿਲਾਂ {time} ਉਡੀਕ ਕਰੋ।",
  "Unable to determine your location. Please check your device's location settings and try again.": "ਤੁਹਾਡੀ ਲੋਕੇਸ਼ਨ ਦਾ ਪਤਾ ਨਹੀਂ ਲੱਗ ਸਕਿਆ। ਕਿਰਪਾ ਕਰਕੇ ਆਪਣੇ ਡਿਵਾਈਸ ਦੀਆਂ ਲੋਕੇਸ਼ਨ ਸੈਟਿੰਗਾਂ ਜਾਂਚੋ ਅਤੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "You are outside the allowed location for this branch.": "ਤੁਸੀਂ ਇਸ ਸ਼ਾਖਾ ਲਈ ਮਨਜ਼ੂਰ ਥਾਂ ਤੋਂ ਬਾਹਰ ਹੋ।",
  "Your browser does not support location access.": "ਤੁਹਾਡਾ ਬ੍ਰਾਊਜ਼ਰ ਲੋਕੇਸ਼ਨ ਦੀ ਪਹੁੰਚ ਦਾ ਸਮਰਥਨ ਨਹੀਂ ਕਰਦਾ।",
  "Choose the filled template first.": "ਪਹਿਲਾਂ ਭਰਿਆ ਹੋਇਆ ਟੈਂਪਲੇਟ ਚੁਣੋ।",
  "Could not cancel the import.": "ਇੰਪੋਰਟ ਰੱਦ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Could not create the error file.": "ਗਲਤੀ ਫਾਈਲ ਨਹੀਂ ਬਣ ਸਕੀ।",
  "Could not download the error report.": "ਗਲਤੀ ਰਿਪੋਰਟ ਡਾਊਨਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Could not download the template.": "ਟੈਂਪਲੇਟ ਡਾਊਨਲੋਡ ਨਹੀਂ ਹੋ ਸਕਿਆ।",
  "Could not open that import.": "ਉਹ ਇੰਪੋਰਟ ਖੋਲ੍ਹੀ ਨਹੀਂ ਜਾ ਸਕੀ।",
  "Could not retry the failed emails.": "ਅਸਫਲ ਈਮੇਲਾਂ ਦੁਬਾਰਾ ਨਹੀਂ ਭੇਜੀਆਂ ਜਾ ਸਕੀਆਂ।",
  "The connection was lost, so the outcome is unknown. Press Confirm again: this import cannot be applied twice.": "ਕੁਨੈਕਸ਼ਨ ਟੁੱਟ ਗਿਆ, ਇਸ ਲਈ ਨਤੀਜਾ ਪਤਾ ਨਹੀਂ। ਦੁਬਾਰਾ \"ਪੁਸ਼ਟੀ ਕਰੋ\" ਦਬਾਓ: ਇਹ ਇੰਪੋਰਟ ਦੋ ਵਾਰ ਲਾਗੂ ਨਹੀਂ ਹੋ ਸਕਦੀ।",
  "The file could not be checked. Nothing was imported.": "ਫਾਈਲ ਦੀ ਜਾਂਚ ਨਹੀਂ ਹੋ ਸਕੀ। ਕੁਝ ਵੀ ਇੰਪੋਰਟ ਨਹੀਂ ਹੋਇਆ।",
  "The import was rejected. Nothing was created.": "ਇੰਪੋਰਟ ਰੱਦ ਕਰ ਦਿੱਤੀ ਗਈ। ਕੁਝ ਵੀ ਨਹੀਂ ਬਣਾਇਆ ਗਿਆ।",
  "{percent}% of headcount · {count} on probation": "ਕੁੱਲ ਸਟਾਫ਼ ਦਾ {percent}% · {count} ਪ੍ਰੋਬੇਸ਼ਨ ਤੇ",
  "across {count} org units": "{count} ਸੰਗਠਨ ਇਕਾਈਆਂ ਵਿੱਚ",
  "all assigned a reporting manager": "ਸਭ ਨੂੰ ਰਿਪੋਰਟਿੰਗ ਮੈਨੇਜਰ ਸੌਂਪਿਆ ਗਿਆ ਹੈ",
