  "Are you sure you want to deactivate {name}?": "ਕੀ ਤੁਸੀਂ ਸੱਚਮੁੱਚ {name} ਨੂੰ ਨਿਸ਼ਕਿਰਿਆ ਕਰਨਾ ਚਾਹੁੰਦੇ ਹੋ?",
  "Could not export the employee directory. Please try again.": "ਕਰਮਚਾਰੀ ਡਾਇਰੈਕਟਰੀ ਐਕਸਪੋਰਟ ਨਹੀਂ ਹੋ ਸਕੀ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
