  "Could not save your feedback.": "ਤੁਹਾਡੀ ਫੀਡਬੈਕ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Write at least {count} characters of comments.": "ਘੱਟੋ-ਘੱਟ {count} ਅੱਖਰਾਂ ਦੀਆਂ ਟਿੱਪਣੀਆਂ ਲਿਖੋ।",
  "Could not resend the onboarding email.": "ਆਨਬੋਰਡਿੰਗ ਈਮੇਲ ਦੁਬਾਰਾ ਨਹੀਂ ਭੇਜੀ ਜਾ ਸਕੀ।",
  "Onboarding email resent.": "ਆਨਬੋਰਡਿੰਗ ਈਮੇਲ ਦੁਬਾਰਾ ਭੇਜ ਦਿੱਤੀ ਗਈ।",
