  "Could not capture the photo. Please try again.": "ਫੋਟੋ ਕੈਪਚਰ ਨਹੀਂ ਹੋ ਸਕੀ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
  "Could not record this leave.": "ਇਹ ਛੁੱਟੀ ਦਰਜ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "End date is before the start date.": "ਅੰਤ ਦੀ ਤਾਰੀਖ ਸ਼ੁਰੂ ਦੀ ਤਾਰੀਖ ਤੋਂ ਪਹਿਲਾਂ ਹੈ।",
  "Half day applies to a single date only.": "ਅੱਧਾ ਦਿਨ ਸਿਰਫ਼ ਇੱਕ ਤਾਰੀਖ ਲਈ ਲਾਗੂ ਹੁੰਦਾ ਹੈ।",
  "Leave recorded — {days} day from {date}.": "ਛੁੱਟੀ ਦਰਜ ਹੋਈ — {date} ਤੋਂ {days} ਦਿਨ।",
  "Leave recorded — {days} days from {date}.": "ਛੁੱਟੀ ਦਰਜ ਹੋਈ — {date} ਤੋਂ {days} ਦਿਨ।",
  "That range contains only weekly offs.": "ਉਸ ਮਿਆਦ ਵਿੱਚ ਸਿਰਫ਼ ਹਫ਼ਤਾਵਾਰੀ ਛੁੱਟੀਆਂ ਹਨ।",
  "Could not download this report.": "ਇਹ ਰਿਪੋਰਟ ਡਾਊਨਲੋਡ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Could not send this report.": "ਇਹ ਰਿਪੋਰਟ ਭੇਜੀ ਨਹੀਂ ਜਾ ਸਕੀ।",
  "Salary saved.": "ਤਨਖਾਹ ਸੁਰੱਖਿਅਤ ਹੋ ਗਈ।",
  "Failed to save the declaration.": "ਘੋਸ਼ਣਾ ਸੁਰੱਖਿਅਤ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "Failed to submit the declaration.": "ਘੋਸ਼ਣਾ ਜਮ੍ਹਾਂ ਨਹੀਂ ਹੋ ਸਕੀ।",
  "That did not go through. Please try again.": "ਇਹ ਪੂਰਾ ਨਹੀਂ ਹੋਇਆ। ਕਿਰਪਾ ਕਰਕੇ ਦੁਬਾਰਾ ਕੋਸ਼ਿਸ਼ ਕਰੋ।",
