  "Enter your landlord's name for the rent you are claiming.": "ਜਿਸ ਕਿਰਾਏ ਦਾ ਤੁਸੀਂ ਦਾਅਵਾ ਕਰ ਰਹੇ ਹੋ, ਉਸ ਲਈ ਆਪਣੇ ਮਕਾਨ ਮਾਲਕ ਦਾ ਨਾਮ ਦਾਖਲ ਕਰੋ।",
  "Landlord PAN is required when your yearly rent is above ₹1,00,000.": "ਜਦੋਂ ਤੁਹਾਡਾ ਸਾਲਾਨਾ ਕਿਰਾਇਆ ₹1,00,000 ਤੋਂ ਵੱਧ ਹੋਵੇ ਤਾਂ ਮਕਾਨ ਮਾਲਕ ਦਾ PAN ਲੋੜੀਂਦਾ ਹੈ।",
